// data/olaylar_ek10.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.OLAYLAR_EK10 = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1479-08-01","k":"fetih","etiket":["toprak-kazanc","denizcilik","konu-askeri"],"b":"İyon adalarının fethi — Tocco düklüğünün sonu: Ayamavra, Kefalonya, Zaklise, İthaki","gun":"Ağustos 1479","yer":"Ayamavra (Lefkada), Kefalonya, Zaklise (Zakynthos), İthaki — İyon Denizi","yer_id":"Ayamavra (Lefkada)","kisiler":"Fatih Sultan Mehmed, Gedik Ahmed Paşa, Leonardo III Tocco","d":"Aynı yılın ocak ayında Venedik'le imzalanan İstanbul Antlaşması İşkodra ve Arnavutluk kıyısını Osmanlı'da bırakmıştı; İyon adaları ise Venedik'in değil, Kefalonya-Zaklise kontluğunu elinde tutan Tocco ailesinin idaresindeydi ve ayrı bir harekâtla alındı. TDV'nin Ayamavra maddesine göre son dük Leonardo Tocco önce Fâtih'in akrabası Milica Brankoviç ile evlenerek sadakatini korumuş, 1464'te eşi ölünce 1477'de Napoli hanedanından Francesca Marzano ile evlenerek padişahı gücendirmişti. İki yıl sonra Avlonya beyi Gedik Ahmed Paşa kumandasındaki donanma Ayamavra'yı güneydeki Kefalonya ile birlikte ele geçirdi; Leonardo ve Francesca İtalya'ya kaçtı. Gedik Ahmed Paşa maddesi aynı harekâtta Zaklise'nin (Zanta) de alındığını kaydeder; Kefalonya kontluğuna bağlı İthaki de bu devirle Osmanlı idaresine girdi. Böylece Adriyatik ağzından Mora'ya uzanan deniz yolu bütünüyle denetim altına alındı. Adalardan Zaklise üç yıl sonra Venedik'e bırakılacak, Kefalonya ile İthaki 1500'de kaybedilecek, yalnız Ayamavra iki yüz yıl Osmanlı'da kalacaktı.","fethedilen":["Ayamavra (Lefkada)","Kefalonya","İthaki","Zaklise (Zakynthos)"],"kaynak":"gedik-ahmed-pasa","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"vassal","kapsam":"ic","t":"1482-01-01","k":"vassal","etiket":["toprak-kazanc","siyaset","konu-askeri","konu-siyasi"],"b":"Crnojeviç Zetası'nın tâbiiyeti ve Cetinje'nin merkez oluşu","gun":"1482","yer":"Cetinje, Lovçen eteği, Karadağ","yer_id":"Cetinje","kisiler":"II. Bayezid, İvan Crnojeviç","d":"İşkodra'nın 1479'da Osmanlı'da kalmasıyla arka bahçesindeki Zeta dağlık bölgesi de imparatorluğun sınırları içine düştü. Bölgeyi elinde tutan Crnojeviç ailesi, Fâtih'in ölümünden sonra tahta çıkan II. Bayezid'in hükümdarlığını tanıyıp haraca bağlanarak iç işlerinde serbest kaldı; İvan Crnojeviç merkezini ovadan çekip Lovçen dağının eteğindeki Cetinje'ye taşıdı ve şehri kurdu. İki yıl sonra buraya yaptırdığı manastır bölgenin dinî merkezi oldu. Böylece Karadağ, haritada doğrudan Osmanlı toprağı olarak değil, açık tonda bir tâbi bölge olarak belirir. TDV'nin Karadağ maddesi hanedanı ve Cetinje piskoposluğunu anar, hâkimiyetin 1514'te İskender Bey (Crnojeviç soyundan, Osmanlı sarayında yetişmiş) eliyle ayrı bir sancağa dönüştüğünü yazar; 1482 yılı ise TDV'de geçmez, Karadağ tarih yazımının verdiği tarihtir. Coğrafyanın sertliği yüzünden buradaki idare hiçbir zaman ovalardaki gibi sıkı işlemedi.","statu_vasal":["Cetinje"],"kaybedilen":["Zaklise (Zakynthos)"],"kaynak":"karadag","duygu":["🎌"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1484-07-15","k":"fetih","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Kili Kalesi'nin fethi — Tuna ağzının kilidi","gun":"15 Temmuz 1484 (20 Cemâziyelâhir 889)","yer":"Kili (Chilia), Tuna deltası, Boğdan sahili","yer_id":"Kili","kisiler":"II. Bayezid, Kırım Hanı Mengli Giray, Boğdan Voyvodası Büyük Ştefan","d":"Boğdan 1455 eylülünden beri yılda iki bin altın haraç ödeyen tâbi bir voyvodalıktı, ama Karadeniz'e açılan iki limanı hâlâ voyvodanın elindeydi ve Tuna'dan gelen ticaret oradan geçiyordu. II. Bayezid saltanatının ilk büyük seferini bu iki limana yaptı. On gün boyunca gece gündüz topa tutulan Kili Kalesi'nin kumandanı teslim olmak zorunda kaldı. Kale doğrudan Osmanlı idaresine alınıp sancak beyliği haline getirildi; XVI. yüzyılın ikinci yarısında Kazak tehlikesi yüzünden kaza yapılıp Rumeli beylerbeyiliğine bağlı Akkirman sancağına bağlandı. Buradan sonra Boğdan haritada iki kademeli görünür: içeride voyvodalık açık tonda tâbi toprak olarak durur, kıyıdaki iki liman ise koyu tonda doğrudan Osmanlı sancağıdır. TDV'nin Boğdan maddesi bu ikisini 'Boğdan'ın anahtarları ve kapıları' diye anar ve bölgenin II. Bayezid zamanında kesin olarak Osmanlı'ya bağlandığını yazar.","fethedilen":["Kili"],"statu_dogrudan":["Kili"],"kaynak":"kili · [TDV: bogdan]","duygu":["🎉"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1484-08-04","k":"fetih","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Akkirman'ın fethi — Dinyester ağzı ve Boğdan'ın Karadeniz kapısının kapanışı","gun":"4 Ağustos 1484","yer":"Akkirman (Cetatea Albă), Dinyester haliç ağzı, Boğdan sahili","yer_id":"Akkirman","kisiler":"II. Bayezid, Boğdan Voyvodası Büyük Ştefan","d":"Kili'nin tesliminden yirmi gün sonra ordu Dinyester ağzındaki Akkirman'ın önüne geldi ve kale 4 Ağustos'ta alındı. Şehir Boğdan'ın en işlek limanıydı; Fâtih devrinde voyvoda III. Petru 1455'te Osmanlı hâkimiyetini tanıyınca Akkirman tüccarlarına ticaret izni verilmişti, şimdi liman doğrudan devletin oldu. Fetihten sonra Rumeli beylerbeyiliğine bağlı bir sancak haline getirilen Akkirman, 1593'te yeni kurulan Özü eyaletine ilhak edildi. Böylece Boğdan'ın kuzeyden Hotin, güneyden Kili ve Akkirman ile çevrelenen dış kabuğu Osmanlı'nın doğrudan denetimine girmeye başladı; voyvodalık iç işlerinde serbest kaldı ama denize çıkışı kalmadı. Haritada arada boş bir bölge yoktur — koyu tonlu liman sancakları ile açık tonlu voyvodalık toprağı birbirine değer; ikisi arasındaki Bucak bozkırı 1538'e kadar hâlâ voyvodalığın parçasıdır.","fethedilen":["Akkirman"],"statu_dogrudan":["Akkirman"],"kaynak":"akkirman","duygu":["🎉"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1499-08-26","k":"fetih","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"İnebahtı'nın teslimi — Korint körfezinin ağzı Venedik'ten alınıyor","gun":"26 Ağustos 1499","yer":"İnebahtı (Lepanto / Naupaktos), Korint körfezi ağzı, Mora","yer_id":"İnebahtı","kisiler":"II. Bayezid, Küçük Davud Paşa, Kemal Reis","d":"İnebahtı 1407'den beri Venedik'in elindeydi ve Korint körfezinin ağzını tutuyordu; körfezin içindeki bütün kıyı bu kalenin menziline bağlıydı. 1499 seferinde kale karadan kuşatıldı, İnebahtı açıklarında Venedik donanmasıyla çarpışan Osmanlı donanması ise denizden kuşatma kuvvetlerine yardımcı oldu. Kaledeki Venedikliler 26 Ağustos'ta kasabayı Osmanlılar'a teslim ettiler. Şehir bundan sonra yüz seksen sekiz yıl Osmanlı'da kaldı, 1687'de Mora'nın kaybıyla yeniden Venedik'e geçti, 1715'te geri alındı. Aynı yazın deniz muharebesi ile bu teslim iki ayrı olaydır: donanma çarpışması Mora'nın batı ucunda, Sapienza-Zonchio sularında cereyan etti; İnebahtı ise Korint körfezinin ağzında bir kara kuşatmasıyla düştü.","fethedilen":["İnebahtı"],"kaynak":"inebahti","duygu":["🎉"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1594-08-28","k":"siyaset","etiket":["isyan","diplomasi","konu-siyasi","konu-diplomasi","konu-isyan"],"b":"Üç voyvodalığın ayaklanması başlıyor — Erdel Kutsal İttifak'a geçti, Osmanlı yanlısı beyler tutuklandı","gun":"28 Ağustos 1594","yer":"Erdel, Eflak ve Boğdan voyvodalıkları","kisiler":"III. Murad, Erdel Prensi Zsigmond Báthory, Eflak Voyvodası Cesur Mihail, Boğdan Voyvodası Aron Vodâ, Papa VIII. Clément, Avusturya Kralı II. Rudolf","d":"Uzun Savaş'ın ikinci yılında Osmanlı'nın Orta Avrupa'daki vasal kuşağı bir anda çözüldü. Papa VIII. Clément'in himayesinde kurulan Kutsal İttifak'a yaz sonunda Boğdan ve Erdel geçti: Boğdan Voyvodası Aron Vodâ 16 Ağustos 1594'te hıristiyan tarafına katılışını bir belgeyle resmîleştirdi, Erdel Prensi Zsigmond Báthory de 28 Ağustos 1594'te savaşa karşı çıkan Osmanlı yanlısı beyleri tasfiye ederek içerideki muhalefeti kırdı. Eflak Voyvodası Cesur Mihail aynı yılın sonbaharında ittifaka katıldı. Böylece Osmanlı'nın Tuna'nın kuzeyindeki üç tâbi prensliği — yüz elli yıldır haraç ödeyen, voyvodası İstanbul'ca onaylanan üç voyvodalık — aynı sonbaharda birden karşı tarafa geçti. Karar 28 Ocak 1595'te Prag'da imzalanan antlaşmayla resmîleşti. Bu, Osmanlı'nın Balkanlar'ın kuzeyindeki dolaylı yönetim düzeninin uğradığı en ağır sarsıntıydı; ayaklanma bastırılacak ama üç prensliğin sadakati bir daha 1526-1593 arasındaki kadar sağlam olmayacaktı.","kaynak":"bogdan + History of Transylvania I (ed. B. Köpeczi, MTA Tarih Enstitüsü) s.118-119 + A.-M. Crăciun, Crisia LIII (2023)","duygu":["🏛"],"kapsam_genis":true,"odak_kimlik":["eflak","bogdan","erdel"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1594-11-01","kesinlik":"ay","k":"savas","etiket":["isyan","savas","konu-askeri","konu-isyan"],"b":"Bükreş ayaklanması ve Tuna kalelerine saldırı","gun":"Kasım 1594","yer":"Bükreş, Yergöğü, İbrail, Hırsova, Silistre ve Bender","yer_id":"Bükreş","kisiler":"Eflak Voyvodası Cesur Mihail, Boğdan Voyvodası Aron Vodâ","d":"Kutsal İttifak kararı bir ay sonra kanla uygulandı: Cesur Mihail Bükreş'te Osmanlı muhafız birliğini ve şehirdeki Levanten alacaklıları kılıçtan geçirdi. Ayaklanma aynı kış Tuna hattına yayıldı; Eflak kuvvetleri Yergöğü, İbrail, Hırsova ve Silistre'ye saldırdı, Boğdan tarafında ise Aron Vodâ Bender'deki Osmanlı muhafızlarına aynı baskını yaptı. Vurulan yerlerin seçimi tesadüf değildir: bunların hepsi voyvodalık toprağı değil, Tuna boyunda doğrudan Osmanlı idaresine bağlı kale ve kazalardı — Yergöğü kazası Niğbolu sancak beyliğine, İbrail 1538'den beri doğrudan devlete, Bender yine 1538'den beri Bucak sancağına bağlıydı. Yani isyan, vasal iç bölgeden değil, o bölgeyi çevreleyen doğrudan Osmanlı kabuğuna vurmuştu. Bu kabuk delinmeden Erdel-Eflak-Boğdan üçgeni Habsburg cephesine bağlanamazdı.","kaynak":"eflak · bogdan + History of Transylvania I (ed. B. Köpeczi, MTA Tarih Enstitüsü) s.118-119 (Kasım)","duygu":["⚔️","😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1595-08-23","k":"savas","etiket":["savas","konu-askeri"],"b":"Kalûgerân Muharebesi — Koca Sinan Paşa'nın Eflak seferi","gun":"23 Ağustos 1595","yer":"Kalûgerân (Călugăreni), Neajlov bataklığı, Eflak","kisiler":"III. Mehmed, Sadrazam Koca Sinan Paşa, Eflak Voyvodası Cesur Mihail","d":"Üç voyvodalığın birden elden çıkması üzerine sadrazam Koca Sinan Paşa büyük bir orduyla Tuna'yı geçti ve Eflak'ı yeniden itaat altına almak üzere yürüdü. Cesur Mihail açık savaşta karşı koyamayacağını bildiğinden orduyu Neajlov'un bataklık geçidinde, Kalûgerân'da bekledi ve dar araziye sıkışan kuvvetlere baskın verdi. Baskından sonra sayıca üstün Osmanlı ordusuna karşı duramayarak kuzeye, dağlara çekildi; Sinan Paşa Bükreş ve Târgovişte'yi işgal edip Eflak'ı doğrudan idareye bağlamayı denedi. Kalûgerân bu yüzden Osmanlı için bir yenilgi değil, seferin tamamlanmasını geciktiren bir baskındı; ama Mihail'in ordusunu koruyabilmiş olması, birkaç hafta sonra Erdel'den gelen yardımla karşı taarruza geçmesini mümkün kıldı.","kaynak":"eflak","duygu":["⚔️"],"yer_kon":[44.2,25.99]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1595-10-01","k":"savas","etiket":["savas","konu-askeri"],"b":"Eflak'tan çekiliş ve Yergöğü baskını — bastırma seferinin sonuçsuz kalışı","gun":"Ekim 1595","kesinlik":"ay","yer":"Yergöğü (Giurgiu), Tuna'nın Eflak yakası","yer_id":"Yergöğü (Giurgiu)","kisiler":"Sadrazam Koca Sinan Paşa, Eflak Voyvodası Cesur Mihail, Erdel Prensi Zsigmond Báthory","d":"Erdel prensinin kuvvetleriyle birleşen Cesur Mihail'in karşı taarruzu üzerine Sinan Paşa Târgovişte ve Bükreş'i boşaltıp Tuna'ya çekildi. Çekilişin en pahalı anı geçit başında yaşandı: 1595 ekiminde Eflak'tan dönen orduyu takip eden akıncılar Yergöğü'nde Mihail'in baskınına uğradılar. Sefer böylece Eflak'ı doğrudan idareye bağlama hedefine ulaşamadan bitti ve voyvodalık fiilen elden çıkmış olarak kaldı. Osmanlı otoritesi bu üçgende ancak yıllar içinde ve parça parça onarılabildi; Erdel'in itaate dönüşü 1604'te Bocskai ayaklanmasını, cephenin bütünüyle kapanması ise 1606 Zitvatorok Antlaşması'nı bekleyecekti.","kaynak":"yergogu","duygu":["⚔️"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1713-06-24","k":"idari","etiket":["toprak-kazanc","idari","konu-askeri","konu-idari"],"b":"Hotin'in Boğdan'dan koparılması — voyvodalığın ortasında doğrudan Osmanlı sancağı","gun":"24 Haziran 1713","yer":"Hotin Kalesi, Dinyester'in sağ yakası, kuzey Boğdan","kisiler":"III. Ahmed, Boğdan Voyvodası Dimitrie Cantemir (1711'de Rusya'ya geçen voyvoda), Demirbaş Şarl","d":"Prut seferinde Boğdan voyvodası Dimitrie Cantemir'in Rusya tarafına geçmesi, voyvodalığın kuzey sınırının artık voyvodaya bırakılamayacağını gösterdi. Bunun üzerine Hotin 1711'den sonra Boğdan'dan alınıp doğrudan Osmanlı idaresine sokuldu; önce bir nahiye, sonra sancak statüsü verildi. 1713'teki geçici Rus işgalinin ardından kale İstanbul'dan gönderilen Osmanlı ve Fransız teknik heyetinin nezaretinde yeniden tamir edilerek genişletildi ve Tuna'nın kuzeyindeki en güçlü Osmanlı istihkâmı hâline geldi. Haritada bu tarihten sonra Hotin'in tâbi voyvodalık tonundan çıkıp doğrudan Osmanlı rengine dönmesi, ve tâbi Boğdan'ın ortasında yalnız bir ada gibi durması işte bu idarî ayrılmanın karşılığıdır — bir çizim hatası değildir. Aynı yapı Bucak'ta 1538'den, Kili ve Akkirman'da 1484'ten beri zaten vardı: voyvodalık iç işlerinde serbest, sınır kaleleri devletin.","statu_dogrudan":["Hotin"],"kaynak":"hotin","duygu":["📋"],"yer_id":"Hotin"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1877-04-24","k":"savas","etiket":["savas","diplomasi","konu-askeri","konu-diplomasi"],"b":"Rusya'nın savaş ilânı — Doksanüç Harbi'nin başlaması","gun":"24 Nisan 1877","yer":"Tuna ve Doğu Anadolu cepheleri","kisiler":"II. Abdülhamid, Serdârıekrem Abdülkerim Nâdir Paşa, Ahmed Muhtar Paşa, Grandük Nikola","d":"1876 Bulgar İsyanı'nın bastırılışı Avrupa kamuoyunda büyük infial uyandırmış, Rusya bunu Bâbıâli'yi yalnızlaştırmak için sonuna kadar kullanmıştı. İstanbul (Tersane) Konferansı'nın Bulgaristan'ı iki muhtar eyalete bölme teklifi ve ardından 31 Mart 1877 tarihli Londra Protokolü Osmanlı Devleti tarafından reddedilince Rusya 24 Nisan 1877'de savaş ilân etti ve ordusu, kendi tarafına çektiği Romanya Prensliği topraklarına girdi (harita Eflak-Boğdan'ı bu andan Edirne Mütarekesi'ne dek Rus ilerleyişinin taralı örtüsüyle gösterir). Rûmî takvimde 1293 yılına rastladığı için savaş Doksanüç Harbi adıyla anılır. Harekât Tuna ve Doğu Anadolu olmak üzere iki cephede yürüdü: Tuna'da 180.000 kişilik Osmanlı ordusu nehrin sol kıyısını birinci, Balkan dağlarını ikinci savunma hattı saymıştı; doğuda Ahmed Muhtar Paşa'nın 55.000 askeri Ardahan-Doğubayazıt arasında mevzilenmişti. Bu savaş haritada Osmanlı Rumelisi'nin çöküşünü başlatan olaydır — Bulgaristan, Sırbistan, Karadağ ve Romanya'nın bugünkü sınırlarının hepsi bu on beş ayın ürünüdür.","kaynak":"doksanuc-harbi","duygu":["⚔️"],"kapsam_genis":true,"yer_kon":[47.0105,28.8638]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1877-08-23","k":"kayip","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Lofça Rus ordusunca işgal edildi","gun":"23 Ağustos 1877","yer":"Lofça (Loveč)","yer_id":"Lofça (Loveč)","kisiler":"Rifat Paşa","d":"93 Harbi'nde Lofça 5 Haziran 1877'de Ruslar tarafından işgal edilmiş, Rifat Paşa komutasındaki Osmanlı kuvvetleri 15 Haziran'da Rusları geri püskürtmüştü; şehir 23 Ağustos'ta Osmanlılarca terk edilerek yeniden Rus işgaline girdi. Harita Lofça'yı bu günden Berlin Antlaşması'na kadar Rus işgali altında (taralı) gösterir; hukuken Osmanlı toprağı olmaya devam eder.","kaynak":"lofca","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1433-01-01","kesinlik":"yil","k":"fetih","etiket":["toprak-kazanc","konu-askeri","konu-siyasi"],"b":"Toplice bölgesi (Kurşunlu, Ürküp) Osmanlı hâkimiyetine girdi","gun":"1433 (YIL; TDV «muhtemel»)","yer":"Kurşunlu (Kuršumlija), Ürküp (Prokuplje), Toplice","yer_id":"Kurşunlu (Kuršumlija)","kisiler":"II. Murad, Mara Brankoviç","d":"II. Murad'ın Mara Brankoviç ile nişanlanması sırasında, Dubočica ve Toplice bölgesinin (Leskofça, Kurşunlu ve Ürküp çevresi) Osmanlı hâkimiyetine geçtiği muhtemel görülmektedir; 1445-1447 tahrir kaydı bölgenin Osmanlı sipahilerine timar olarak verildiğini gösterir. Haritada Kurşunlu ve Ürküp bu yıldan itibaren Osmanlı idaresindedir.","kaynak":"leskofca","duygu":["⚔️"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1877-05-21","k":"kayip","etiket":["toprak-kayip","siyaset","konu-siyasi","konu-askeri"],"b":"Romanya'nın bağımsızlığını ilân etmesi — Eflak-Boğdan tâbiliğinin sonu","gun":"21 Mayıs 1877 (9 Mayıs O.S.)","yer":"Bükreş","yer_id":"Bükreş","kisiler":"Prens I. Carol","d":"93 Harbi'nin ilânından iki hafta sonra Romanya Prensliği bağımsızlığını ilân etti ve savaşa Rusya'nın yanında girdi; Plevne kuşatmasındaki payı Osmanlı yenilgisinde belirleyici oldu. Dört yüz yılı aşkın Eflak ve Boğdan tâbiliği böylece fiilen sona erdi; bağımsızlık Berlin Kongresi'nde (1878) uluslararası tanıma kazandı. Harita bu tarihten itibaren Romanya'yı tâbi değil kendi rengiyle bağımsız devlet olarak gösterir. Bağımsızlık ilanıyla Eflak ve Boğdan'ın tamamı (Yaş, Kalas, İbrail, Yergöğü, Calafat, Botoşani vd.) bağımsız Romanya oldu.","kaynak":"romanya · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): TDV İslâm Ansiklopedisi, 'Romanya', https://islamansiklopedisi.org.tr/romanya","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1832-01-01","k":"kayip","etiket":["toprak-kayip","diplomasi","konu-diplomasi"],"b":"İzdin (Lamia) Yunanistan sınırları içinde kaldı — Arta-Volos hattı","gun":"1832","yer":"İzdin (Lamia)","yer_id":"İzdin (Lamia)","d":"Bağımsız Yunan devletinin kuzey sınırı 1832'de Arta körfezinden Volos körfezine uzanan hatta çizildi. Osmanlı döneminde (1424-1832) Eğriboz sancağına bağlı bir kaza merkezi olan İzdin, bu hattın güneyinde kaldığı için Yunanistan'a geçti; Tesalya'nın geri kalanı (Yenişehir, Tırhala) 1881'e kadar Osmanlı'da kaldı.","kaynak":"izdin","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1877-06-27","k":"kayip","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Rus ordusunun Tuna'yı geçmesi — Ziştovi ve Tırnova'nın düşüşü","gun":"27 Haziran 1877","yer":"Ziştovi (Sviştov), Tuna'nın sağ yakası","kisiler":"Grandük Nikola, Abdülkerim Nâdir Paşa","d":"Savaşın başlamasıyla Romanya topraklarına giren ve bu prensliği kendi tarafına çeken Ruslar, biri Dobruca diğeri Bükreş istikametinde olmak üzere iki koldan ilerledi. Tuna, Rusçuk ile Niğbolu arasından geçildi ve 27 Haziran'da Ziştovi, 1 Temmuz'da eski Bulgar başşehri Tırnova ele geçirildi. Tahliyesi emredildiği halde bu hususa itina gösterilmediği için Niğbolu da bir müddet direndikten sonra teslim oldu. Birinci savunma hattının bir hafta içinde yarılması İstanbul'da büyük paniğe yol açtı; saltanat merkezinin Bursa'ya nakledileceğine dair haberler bile yayıldı ve savaşın idaresi başşehirde kurulan bir askerî meclise devredildi.","kaynak":"doksanuc-harbi","duygu":["😔"],"yer_kon":[43.62,25.35]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1877-07-19","k":"kayip","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Şıpka Geçidi'nin tahliyesi — Balkan hattının yarılması","gun":"19 Temmuz 1877","yer":"Şıpka Geçidi, Balkan (Stara Planina) dağları","kisiler":"General Gurko, Süleyman Paşa","d":"Balkan dağlarını aşan geçitlerin en stratejiği olan Şıpka'daki Osmanlı kuvvetleri Rus saldırılarına şiddetle karşı koydular; ancak yenileceklerine kanaat getirince 19 Temmuz'da geçidi gizlice tahliye ettiler. Böylece ikinci savunma hattı da açıldı ve General Gurko 22 Temmuz'da Eski Zağra'yı ele geçirdi. Karadağ tarafından yetişen Süleyman Paşa Gurko'yu yenilgiye uğratıp Balkanların güneyindeki işgal altındaki yerleri geri aldıysa da 21 Ağustos'tan itibaren aylarca süren taarruzlara rağmen Şıpka'yı geri alamadı. Haritada bu, Balkan sıradağlarının kuzeyi ile güneyi arasındaki savunma bütünlüğünün bir daha kurulamamasıdır: Tuna cephesindeki mücadele bundan sonra Plevne'de düğümlenecektir.","kaynak":"doksanuc-harbi","duygu":["😔"],"yer_kon":[42.75,25.33]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1877-11-18","k":"kayip","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Kars'ın düşüşü — Doğu cephesinin çözülmesi ve Aziziye tabyaları","gun":"18 Kasım 1877","yer":"Kars Kalesi ve Erzurum-Aziziye tabyaları","kisiler":"Ahmed Muhtar Paşa, General Melikof, General Lazarof, Nene Hatun","d":"Doğu Anadolu'da Kars, Doğubayazıt ve Ardahan'a doğru üç koldan ilerleyen Ruslar 30 Nisan'da Doğubayazıt'ı almış, Ardahan'a girmiş, fakat Erzurum üzerine yürürken 15 Temmuz'da mağlûp edilerek sınır dışına atılmışlardı. Ahmed Muhtar Paşa'ya \"Gazi\" unvanını kazandıran bu başarı ağustosta General Lazarof'un yeniden taarruza geçmesiyle tersine döndü ve 18 Kasım'da Kars düştü. Daha uygun bir savunma için Erzurum'a çekilen Osmanlı kuvvetleri Aziziye tabyalarında, Nene Hatun'un ahaliyi teşvikiyle büyük bir mukavemet gösterdi. Kars, Ardahan ve Batum sekiz ay sonra Berlin'de harp tazminatının bir kısmına karşılık Rusya'ya bırakılacaktır.","kaynak":"doksanuc-harbi","duygu":["😔"],"yer_id":"Kars"},{"onem":4,"dunya":3,"bolge_onem":5,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1912-10-08","k":"savas","etiket":["savas","ittifak","toprak-kayip","konu-askeri","konu-diplomasi"],"b":"I. Balkan Savaşı'nın başlaması — Karadağ'ın savaş ilânı","gun":"8 Ekim 1912","yer":"Arnavutluk ve Yenipazar sancağı","kisiler":"Karadağ Kralı Nikola, Sadrazam Gazi Ahmed Muhtar Paşa, Hariciye Nâzırı Noradungiyan Efendi","d":"Balkan devletleri, İttihat ve Terakkî'nin 3 Temmuz 1911 tarihli kanunla kiliseler meselesini çözmesinin ardından aralarındaki en büyük engeli kaldırmış, Rusya'nın kışkırtmasıyla 1912 boyunca birbirleriyle ittifak antlaşmaları imzalamışlardı (13 Mart'ta Sırbistan-Bulgaristan, 29 Mayıs'ta Bulgaristan-Yunanistan, ağustosta Karadağ-Bulgaristan, 6 Ekim'de Karadağ-Sırbistan). Bâbıâli bunu farketmedi; hatta Rusya'nın teminatına güvenerek Rumeli'deki 120 tâlimli taburu terhis etti. Dört devlet 3 Ekim'de ortak nota vererek Makedonya, Arnavutluk ve Girit'e muhtariyet istedi; cevap alamayınca 8 Ekim 1912'de Karadağ'ın savaş ilânıyla harekât başladı. 13 Ekim'de Sırbistan ve Bulgaristan elçilerinin pasaportları ellerine verildi, ertesi gün bu iki devlet, ardından Yunanistan savaş ilân etti. Savaş sırasında ordu içindeki siyasî görüş ayrılıkları yenilgide büyük rol oynadı.","kaynak":"balkan-savasi","duygu":["⚔️"],"yer_id":"Yenipazar (Novi Pazar)"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1912-10-23","k":"kayip","etiket":["savas","toprak-kayip","konu-askeri"],"b":"Şark Ordusu'nun bozgunu ve Çatalca hattına çekiliş — Kumanova ve Selânik'in kaybı","odak_yer":["Çatalca","Selanik"],"gun":"23 Ekim 1912","yer":"Doğu Trakya (Çatalca hattı), Kumanova, Selânik","kisiler":"Tahsin Paşa, Gazi Ahmed Muhtar Paşa, Kâmil Paşa","d":"Osmanlı Şark Ordusu 23 Ekim 1912'de kendisinden üç kat kalabalık Bulgar ordusuna yenilerek İstanbul'un otuz kilometre batısındaki Çatalca hattına kadar çekildi; başşehir savaşın ilk ayında doğrudan tehdit altına girdi. Aynı günlerde Garp Ordusu 23-24 Ekim'de Kumanova'da Sırplar'a yenildi ve Tahsin Paşa 35.000 kişilik ordusuyla Selânik'te Yunanlılar'a teslim oldu. Bu bozgunlar üzerine 29 Ekim'de Gazi Ahmed Muhtar Paşa kabinesi istifa etti; Selânik'te sürgün hayatı süren II. Abdülhamid 1 Kasım'da İstanbul'a nakledildi. Çatalca hattı savaşın sonuna kadar tutuldu — Rumeli'nin beş yüz yıllık Osmanlı coğrafyası birkaç hafta içinde bu dar şeride indi.","kaynak":"balkan-savasi","duygu":["😔"],"kapsam_genis":true},{"kapsam":"ic","t":"1912-10-20","k":"kayip","onem":3,"dunya":2,"yer_id":"Kırcaali","b":"Rodoplar'da Kırcaali Müfrezesi bozuldu, Kırcaali düştü","gun":"20 Ekim 1912","yer":"Kırcaali, Rodoplar","kisiler":"Mehmed Yaver Paşa","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Bulgar savaş ilânının ardından Rodoplar'dan inen Bulgar kuvvetleri, Mehmed Yaver Paşa'nın Kırcaali Müfrezesi'ni yenerek Kırcaali'ye girdi. Bozguna uğrayan müfreze Gümülcine yönüne çekildi; Rodoplar'ın doğu kesimi savaşın ilk haftasında elden çıktı.","kaynak":"Sinan Koçak, 'Bulgar Yazar İvan Lesiçkof'un Gözünden Balkan Harbinde Kırcaali Müfrezesi', JUHIS 2(1), 2019, s.9 (dergipark 741217): '20 Ekim’de Bulgar askerinin Osmanlı ordusunu mağlup ederek Kırcaali’ye girdiği bilinmektedir'"},{"kapsam":"ic","t":"1912-10-23","k":"kayip","onem":3,"dunya":2,"yer_id":"Yenipazar (Novi Pazar)","b":"Yenipazar sancağının merkezine Prens Aleksandar girdi","gun":"23 Ekim 1912","yer":"Yenipazar (Novi Pazar), Yenipazar sancağı","kisiler":"Prens Aleksandar","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Sırp kuvvetleri savaşın ilk haftasında Yenipazar'ı aldı ve batıdan gelen Karadağ kuvvetleriyle birleşti. Sırbistan ile Karadağ'ı yüz yıldır ayıran Yenipazar sancağı böylece iki müttefik arasında köprüye dönüştü.","kaynak":"Sinan Koçak, JUHIS 2(1), 2019, s.5 (dergipark 741217), Çalık 2015'e atıfla: '23 Ekimde Prens Aleksandr Yenipazarı ele geçirdikten sonra batıdan gelen Karadağ ve doğudan gelen Bulgar kuvvetleriyle birleşti'"},{"tur":"savas","kapsam":"ic","t":"1912-10-24","k":"kayip","onem":3,"dunya":2,"yer_id":"Kırklareli","b":"Kırkkilise muharebesinin ardından Kırklareli elden çıktı","gun":"24 Ekim 1912","yer":"Kırklareli (Kırkkilise)","kisiler":"Kölemen Abdullah Paşa","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Doğu Trakya'da Şark Ordusu'nun Kırkkilise muharebesinde yenilmesi üzerine Kölemen Abdullah Paşa'nın savunduğu şehir Bulgar kuvvetlerine bırakıldı. Şehir dokuz ay süren işgalden ancak II. Balkan Savaşı'nda, 21 Temmuz 1913'te kurtarıldı.","kaynak":"kirklareli — gövde okundu: 'Kırkkilise, Balkan Savaşı’nın başlarında 24 Ekim 1912 tarihinde Bulgar kuvvetlerince işgal edildi. Şehir dokuz ay kadar süren bu işgalden 21 Temmuz 1913’te kurtarıldı.'"},{"kapsam":"ic","t":"1912-10-26","k":"kayip","onem":4,"dunya":3,"yer_id":"Üsküp","b":"Kosova vilâyetinin merkezi Üsküp direnişsiz bırakıldı","gun":"26 Ekim 1912","yer":"Üsküp (Skopje)","kisiler":"Prens Aleksandar","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Kumanova bozgunundan (23-24 Ekim) sonra Kosova vilâyetinin merkezi Üsküp savunmasız kaldı. Halkın şehir çevresinde çarpışma istememesi üzerine konsoloslar aracılığıyla davet edilen Prens Aleksandar komutasındaki Sırp kuvvetleri 26 Ekim akşamı şehre direnişsiz girdi.","kaynak":"Yakup Ahbab, 'Kuzey Makedonya 1912', İÜ Tarih Dergisi (dergipark 353908) s.11: '26 Ekim akşamı … Kumanova’dan gelen Prens Aleksandr komutasındaki Sırp kuvvetleri hiçbir direnişle karşılaşmadan … ' · Ayşe Özkan, Tarihin Peşinde 15, s.12: '26 Ekim akşamı Üsküp Sırplara teslim olurken'"},{"kapsam":"ic","t":"1912-10-28","k":"kayip","onem":3,"dunya":2,"yer_id":"Köprülü (Veles)","b":"Vardar boyunda Köprülü (Veles) kaybedildi","gun":"28 Ekim 1912","yer":"Köprülü (Veles), Vardar vadisi","kisiler":"Sırp ordusu","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Üsküp'ün düşüşünden iki gün sonra Vardar boyunca güneye inen Sırp ordusu Köprülü'yü aldı. Vardar vadisinin Selanik'e açılan kapısı böylece Sırpların eline geçti.","kaynak":"Ayşe Özkan, 'Balkan Savaşları'nda Sırpların Müslümanlara Yönelik Gayri İnsanî Uygulamaları', Tarihin Peşinde 15, s.12: '28 Ekim’de Köprülü, 29 Ekim’de İştip … arka arkaya Sırp işgaline uğramıştır' · TDV koprulu: '1912 yılının sonbaharında Sırp ordusu Köprülü’yü ele geçirdi'"},{"kapsam":"ic","t":"1912-10-29","k":"kayip","onem":3,"dunya":2,"yer_id":"İştip (Štip)","b":"Bregalnitsa havzası: General Stefanoviç İştip'e girdi","gun":"29 Ekim 1912","yer":"İştip (Štip)","kisiler":"General Stefanoviç","etiket":["savas","toprak-kayip","konu-askeri"],"d":"General Stefanoviç komutasındaki Sırp birlikleri İştip'i direnişle karşılaşmadan aldı; şehre önce düzensiz çeteler girdi. Kumanova'nın ardından doğu Makedonya'nın Bregalnitsa havzası Sırp denetimine geçti.","kaynak":"Özkan, Tarihin Peşinde 15, s.12 ve s.16: '29 Ekim’de İştip’i ele geçiren General Stefanoviç komutasındaki Sırp birlikleri hiçbir direnişle karşılaşmamışlardır' · TDV istip: '1912 Ekimi sonunda … Sırp ordusu şehri işgal etti'"},{"kapsam":"ic","t":"1912-10-29","k":"kayip","onem":3,"dunya":2,"yer_id":"Karaferye (Veria)","gs":20,"b":"Sarantaporo geçidinden sonra Karaferye Yunan hâkimiyetine geçti","gun":"29 Ekim 1912 (TDV: 16 Ekim — eski takvim)","yer":"Karaferye (Veria)","kisiler":"Yunan ordusu","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Tesalya'dan kuzeye ilerleyen Yunan ordusu Sarantaporo (Kırkgeçit) geçidini aştıktan sonra Karaferye'ye hâkim oldu. Şehrin müslüman nüfusunun bir kısmı bu sırada bölgeyi terk etti.","kaynak":"karaferye — gövde okundu: 'Balkan savaşları sırasında Yunan ordusu şehre hâkim oldu (16 Ekim 1912)'"},{"kapsam":"ic","t":"1912-10-31","k":"kayip","onem":3,"dunya":2,"yer_id":"Vodina (Edessa)","b":"Selanik-Manastır demiryolu üzerindeki Vodina kaybedildi","gun":"31 Ekim 1912 (TDV: 18 Ekim — eski takvim)","yer":"Vodina (Edessa)","kisiler":"Yunan ordusu","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Selanik-Manastır demiryolu üzerindeki Vodina Yunan ordusunun eline geçti. Slav ve Türk nüfusun zorla ayrılmasıyla şehrin nüfusu kısa sürede ciddi biçimde geriledi.","kaynak":"vodina — gövde okundu: '18 Ekim 1912’de Vodina, Yunan ordusu tarafından ele geçirildi'"},{"tur":"savas","kapsam":"ic","t":"1912-11-02","k":"kayip","onem":3,"dunya":2,"yer_id":"Yenice-i Vardar","b":"Yenice Muharebesi — Yenice-i Vardar'ın Yunanlılara geçmesi","gun":"1-2 Kasım 1912","yer":"Yenice-i Vardar (Giannitsa)","kisiler":"Hasan Tahsin Paşa","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Hasan Tahsin Paşa'nın 8. Mürettep Kolordusu Selanik'in batısındaki Yenice'de Yunan ordusuna yenildi ve Selanik bölgesine çekildi. Muharebe sırasında kasabanın büyük bölümü yandı; Selanik'in yolu Yunan ordusuna açıldı.","kaynak":"Salim Aydın, Türk Kültürü İncelemeleri Dergisi 38 (2018) (dergipark 3173273) s.27: 'Yenice Muharebesi … (1-2 Kasım 1912). Bu muharebeden sonra Selânik bölgesine çekilmiştir' · TDV yenice-i-vardar: 'Yannitsa savaşı esnasında … Yenice-i Vardar’ın büyük bölümü yakılmış'"},{"kapsam":"ic","t":"1912-11-03","k":"kayip","onem":3,"dunya":2,"yer_id":"Prizren","b":"Prizren Kosova'nın güneybatısında teslim oldu","gun":"3 Kasım 1912","yer":"Prizren","kisiler":"Sırp ordusu","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Kosova'nın güneybatısındaki Prizren Sırp kuvvetlerine teslim oldu. Şehre giren birliklerin müslüman ahaliye karşı tutumu, savaşın Kosova'daki en ağır sayfalarından biri olarak kaydedildi.","kaynak":"Özkan, Tarihin Peşinde 15, s.12: '3 Kasım’da Prizren Sırplara teslim olmuştur' (s.16 aynı gün)"},{"kapsam":"ic","t":"1912-11-05","k":"kayip","onem":3,"dunya":2,"yer_id":"Ustrumca (Strumica)","b":"Albay Mitov Ustrumca'da sıkıyönetim ilân etti","gun":"5 Kasım 1912","yer":"Ustrumca (Strumica)","kisiler":"Albay Mitov","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Bulgar Albay Mitov Ustrumca'ya girerek sıkıyönetim ilân etti; ertesi gün ayrılırken kasabayı bir Bulgar kaymakama ve bir Sırp komutana bıraktı. Ustrumca savaş boyunca müttefikler arasında el değiştirdi ve 1913'te Bulgaristan'a bağlandı.","kaynak":"Özkan, Tarihin Peşinde 15, s.20: '5 Kasım’da Bulgar Albay Mitov Ustrumca’ya girince sıkıyönetim ilan etmiş' · TDV ustrumca: 'önce Bulgarlar, daha sonra Sırplar … tarafından işgal edildi'; '1913’ten 1919 yılına kadar … Bulgaristan Devleti’ne katıldı'"},{"kapsam":"ic","t":"1912-11-08","k":"kayip","onem":4,"dunya":3,"yer_id":"Selanik","b":"Hasan Tahsin Paşa Selanik'i Yunanlılara bıraktı","gun":"8 Kasım 1912 (TDV: 26 Ekim — eski takvim)","yer":"Selanik","kisiler":"Hasan Tahsin Paşa","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Yenice yenilgisinden sonra Selanik'e çekilen Hasan Tahsin Paşa, Bulgar ordusu kuzeyden yaklaşırken şehri Yunanlılara bıraktı; Yunan ordusu 8 Kasım öğle saatlerinde şehre girdi. Osmanlı Rumeli'sinin en büyük liman şehri ve İttihat ve Terakkî'nin doğduğu Selanik böylece elden çıktı.","kaynak":"Mahmut Akkor, ABAD 8(15), 2025 (dergipark 4696099) s.6: 'Yunan ordusu, Bulgaristan’dan hızlı davranarak 8 Kasım 1912 günü öğle saatlerinde Selanik’e girdi' · TDV selanik: 'Vali Hasan Tahsin Paşa şehri 26 Ekim 1912’de Yunanlılar’a bıraktı' (Jülyen = 8 Kasım)"},{"kapsam":"ic","t":"1912-11-21","k":"kayip","onem":3,"dunya":2,"yer_id":"Gümülcine","b":"Batı Trakya'nın merkezi Gümülcine Bulgarlara açıldı","gun":"21 Kasım 1912","yer":"Gümülcine, Batı Trakya","kisiler":"Mehmed Yaver Paşa","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Kırcaali'den çekilen Yaver Paşa müfrezesinin Fere'ye doğru geri çekilmesi üzerine Gümülcine Bulgar kuvvetlerine teslim oldu. Batı Trakya'nın merkezi, savaşın sonunda Bulgaristan'a bırakılacak toprakların başında geliyordu.","kaynak":"Sinan Koçak, JUHIS 2(1), 2019 (dergipark 741217) s.11: 'Gümülcine, 21 Kasım günü teslim oldu'"},{"kapsam":"ic","t":"1912-11-28","k":"kayip","onem":3,"dunya":2,"yer_id":"Debre (Dibra)","b":"İlbasan'a varan Sırplar aynı gün Debre'ye girdi","gun":"28 Kasım 1912","yer":"Debre (Dibra)","kisiler":"Sırp ordusu","etiket":["savas","toprak-kayip","konu-askeri"],"d":"Manastır'dan batıya ilerleyen Sırp kuvvetleri İlbasan'a vardıkları gün Debre'ye de girdi ve Adriyatik'e doğru indi. Aynı gün Avlonya'da Arnavutluk'un istiklâli ilân ediliyordu.","kaynak":"Özkan, Tarihin Peşinde 15, s.13 ve s.19: '28 Kasım’da Elbasan’a varan Sırplar aynı gün Debre’ye girmişler ve Adriyatik’e inmişlerdir'"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1476-02-01","k":"kayip","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Böğürdelen'in Macarlara kaybı — Sava hattındaki ilk gedik","gun":"Şubat 1476","yer":"Böğürdelen (Šabac), Sava nehri kıyısı","yer_id":"Böğürdelen (Šabac)","kisiler":"Fatih Sultan Mehmed, Macar Kralı Mátyás Corvin","d":"Fâtih Sultan Mehmed zamanında Osmanlı eline geçen ve daha önce Zaslon adıyla anılan mevkide 1471'de ahşap ve topraktan bir hisar yapılmıştı. Belgrad'ı tehdit eden bir noktada bulunduğu ve buradan Macaristan ile Avusturya'nın güney bölgelerine kolayca akın yapılabildiği için kale, adını da bu işlevden alıyordu — Böğürdelen, \"yandan vuran tabya\" demektir. Macar Kralı Mátyás Corvin 1475 sonlarına doğru kaleyi kuşattı ve 1476 şubatında ele geçirdi. Kuşatmayı anlatan Szabács viadala adlı Macar destanı, XV. yüzyıl Macar tarih şiirlerinin metni günümüze ulaşan en uzun örneklerindendir. Macarlar bölgede bir banlık kurdu ve kaleyi taştan yeniden tahkim ederek serhad hisar zincirinin halkası yaptılar. Osmanlılar 1492'de geri almayı denediler ve başaramadılar; kale kırk beş yıl Macar elinde kaldı.","kaybedilen":["Böğürdelen (Šabac)"],"kaynak":"bogurdelen","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1521-07-07","k":"fetih","etiket":["toprak-kazanc","savas","konu-askeri"],"b":"Böğürdelen'in fethi — Kanûnî'nin aldığı ilk kale ve Belgrad kararının verildiği yer","gun":"7 Temmuz 1521","yer":"Böğürdelen (Šabac), Sava nehri kıyısı","yer_id":"Böğürdelen (Šabac)","kisiler":"Kanûnî Sultan Süleyman, Rumeli Beylerbeyi Ahmed Paşa","d":"Kanûnî Sultan Süleyman'ın birinci Macaristan seferinde bölgeye gönderilen Rumeli Beylerbeyi Ahmed Paşa'nın kuvvetleri, şiddetli bir kuşatmanın ardından kaleyi 7 Temmuz 1521'de aldı. Böğürdelen, Kanûnî'nin saltanatında fethedilen ilk kaledir. Padişah fetihten sonra bizzat kaleye girdi ve şehrin imarını emretti; Belgrad'ın fethine dair kararlar da burada alındı — yani 29 Ağustos 1521'de düşecek olan Belgrad'ın planı Böğürdelen'de yapıldı. Kale bundan sonra iki yüz yıla yakın Osmanlı elinde kaldı; önce Rumeli, 1580'den itibaren Bosna eyaletine, ardından kısa süre Semendire ve nihayet İzvornik sancağına bağlandı. Haritada bu tarih Sava hattının Osmanlı lehine kapandığı gündür.","fethedilen":["Böğürdelen (Šabac)"],"kaynak":"bogurdelen","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1788-04-24","k":"kayip","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Böğürdelen'in ikinci Avusturya işgali — Sava cephesinin açılması","gun":"24 Nisan 1788","yer":"Böğürdelen (Šabac), Sava nehri kıyısı","kisiler":"I. Abdülhamid, Avusturya İmparatoru II. Joseph","d":"Avusturya'nın 9 Şubat 1788'de Rusya'nın yanında savaşa girmesinin ardından Sava hattı yeniden cephe oldu ve Böğürdelen 24 Nisan 1788'de Avusturya hâkimiyetine geçti. Kale daha önce 17 Ağustos 1717'de savaşsız olarak Avusturya'ya terkedilmiş ve Belgrad Antlaşması'na (1739) kadar elde tutulmuştu; o dönemde nüfusu öylesine azalmıştı ki şehirde otuz dört hıristiyan evi kalmış, hiç müslüman kalmamıştı. 1739-1788 arasındaki Osmanlı devrinde nüfus yeniden 1500-2000'e çıkmıştı. İkinci işgal Ziştovi Antlaşması'yla (4 Ağustos 1791) sona erecek ve kale Osmanlılar'a iade edilecekti.","kaybedilen":["Böğürdelen (Šabac)"],"kaynak":"bogurdelen","duygu":["😔"],"yer_id":"Böğürdelen (Šabac)"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1806-01-26","k":"kayip","etiket":["toprak-kayip","isyan","konu-askeri","konu-isyan"],"b":"Böğürdelen'in Kara Yorgi'ye teslimi — Birinci Sırp İsyanı'nda ilk kale","gun":"26 Ocak 1806","yer":"Böğürdelen (Šabac), Sava nehri kıyısı","kisiler":"III. Selim, Karadjordje (Kara Yorgi) Petroviç","d":"1804'te Belgrad'daki dayı ve yamakların baskısına tepki olarak başlayan, sonra milliyetçi bir karakter kazanan ilk Sırp ihtilâli sırasında Böğürdelen Kalesi 26 Ocak 1806'da Kara Yorgi'ye teslim edildi. Sava üzerindeki bu kale, isyancıların ele geçirdiği ilk büyük Osmanlı istihkâmıdır ve Belgrad'ın düşüşünü haber verir. İsyan 1813'te bastırılıp Belgrad geri alınınca kale de Osmanlı idaresine döndü; ancak 1830 fermanının garnizon şartıyla Böğürdelen, Belgrad, Semendire ve Fethülislâm ile birlikte özerk Sırbistan'ın içinde Osmanlı askerinin kaldığı dört kaleden biri olarak tanımlandı ve 1867'de garnizonu çekilene kadar bu statüde kaldı.","kaybedilen":["Böğürdelen (Šabac)"],"kaynak":"bogurdelen","duygu":["😔"],"yer_id":"Böğürdelen (Šabac)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1457-01-01","k":"fetih","etiket":["toprak-kazanc","idari","konu-askeri","konu-idari"],"b":"Podgorica'nın Osmanlı topraklarına katılması — Zeta ovasının denetim altına alınması","gun":"1457","yer":"Podgorica (Ribnica), Morača ile Ribnica'nın kavuştuğu yer, Zeta ovası","yer_id":"Podgorica","kisiler":"Fatih Sultan Mehmed","d":"İşkodra gölünün yirmi kilometre kuzeyinde, Morača ile Ribnica sularının birleştiği ovada kurulu kasaba kaynaklarda ilk defa 1216'da Ribnica, 1326'da Podgorica adıyla anılır. 1457'de Osmanlı topraklarına katıldı ve Zeta ovasının denetimi böylece Balšić-Crnojević hânedanlarının elinden çıktı. Fâtih Sultan Mehmed 1474-1478 yılları arasında iki nehrin kavşağındaki sarp kayalıklara bir kale ile cami inşa ettirdi; 1479'da İşkodra'nın fethinden sonra bölge yeni kurulan İşkodra sancağına bağlandı. 1485 tahririnde kırk hânelik hıristiyan bir kasaba olan Podgorica, 1529-30'da 800 kişiye ve kale içinde bir dizdarın emrindeki otuz iki kişilik garnizona, 1582'de 322 hâneye ulaştı. Evliya Çelebi 1662'de Fâtih Kalesi'nde üç yüz ev, ambarlar, cebehâneler ve yedi yüz muhafız saydı. Bu kayıtlar Zeta'nın ovası ile dağı arasındaki farkı da gösterir: ova sayılan, vergilendirilen ve garnizonlu bir Osmanlı kazasıdır — oysa XVIII. yüzyılda şehir, Karadağ dağlarındaki aşiretlerin baskınlarını önlemek için altı tabya ve üç kapılı surlarla tahkim edilmek zorunda kalacaktır. Podgorica 1876-1878 savaşının sonlarında Karadağ'ın eline geçti ve Berlin Antlaşması'yla orada kaldı.","fethedilen":["Podgorica"],"kaynak":"podgorica","duygu":["🎉"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1448-01-01","k":"fetih","etiket":["toprak-kazanc","idari","konu-askeri","konu-idari","konu-imar"],"b":"Saray ovasının ilhakı — Bosna içindeki Osmanlı ucunun kurulması","gun":"1448","yer":"Hodidjed, Saray ovası (Vrhbosna), orta Bosna","kisiler":"II. Murad, Üsküp beyi İshak Bey, oğlu Îsâ Bey","d":"Bosna kralları 1428-1429'da haraca bağlandıktan sonra Osmanlılar krallığın içine doğru kalıcı biçimde yerleşmeye başladı. 1428-1435 arasında Hodidjed kasabası alındı; 852'de (1448) Hodidjed vilâyeti Saray ovasıyla birlikte tamamen Osmanlı idaresine girdi. Bu, Bosna'nın fethinden on beş yıl önce krallığın ortasında kurulmuş bir uç sahasıdır ve voyvoda unvanı taşıyan Üsküp beyi Îsâ Bey tarafından idare edilmiştir — çevresinde hâlâ Osmanlı'ya tâbi Bosna beyleri bulunduğu için bölge çift taraflı denetim altındaydı. Şehrin kendisi de bu dönemde doğdu: 1462'den önce İshak Bey ya da oğlu Îsâ Bey ilk müslüman mahallesini kurdu, 862'de (1458) Fâtih adına Hünkâr Camii yapıldı ve Brodec köyünün ekinliği imar edilerek Saray kasabası ortaya çıktı. 1463'teki fetih Bosna Krallığı'nı ortadan kaldırdı; Saray ovası ise o tarihte zaten on beş yıldır Osmanlı toprağıydı.","fethedilen":["Saraybosna"],"kaynak":"saraybosna","duygu":["🎉"],"yer_id":"Saraybosna"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1465-01-01","k":"fetih","etiket":["toprak-kazanc","idari","konu-askeri","konu-idari"],"b":"Foça'nın alınışı — Hersek Düklüğü'ne ilk girişin açılması","gun":"1465","yer":"Foça (Foča), Drina vadisi, Hersek","yer_id":"Foça (Foča)","kisiler":"Fatih Sultan Mehmed, Hersek Dükü Stjepan Vukçiç-Kosaça","d":"Bosna Krallığı 1463'te ortadan kaldırıldıktan sonra sıra, krallıktan ayrılıp kendi düklüğünü kuran Stjepan Vukçiç-Kosaça'nın topraklarına geldi. Drina vadisinde, İstanbul'u Dubrovnik'e bağlayan ticaret yolunun kavşağında bulunan Foça 1465'te Osmanlı idaresine girdi. Şehrin önemi hemen anlaşıldı: 1470'te yeni teşkil edilen Hersek sancağının merkezi yapıldı — yani Hersek'in idarî çekirdeği, düklüğün kendisi daha yıkılmadan Foça'da kuruldu. Düklüğün tamamının ilhakı 1483'e kadar sürecekti. Foça bundan sonra elverişli iklimi ve yol kavşağındaki konumu sayesinde bir ticaret ve idare merkezi olarak gelişti. Haritada bu tarih, Bosna'nın fethinden sonra güneye doğru ikinci dalganın başladığı gündür.","fethedilen":["Foça (Foča)"],"kaynak":"foca","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1469-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Livno ve batı Bosna'nın kesin ilhakı — Venedik sınırının kurulması","gun":"1468-1469","yer":"Livno (İhlevne), Livno ovası, batı Bosna","yer_id":"Livno (İhlevne)","kisiler":"Fatih Sultan Mehmed, Ivaniš Vlatković","d":"Livno ovasına hâkim plato üzerindeki kale, 1448-1454 arasında Hersek Düklüğü'nün kurucusu Stjepan Vukçiç-Kosaça'nın elindeydi. 1463 Bosna seferinde kısa bir süre Osmanlı kuvvetlerince işgal edilmiş, ancak aynı yıl geri alınmıştı; 1466'da şehrin hâkimi Ivaniš Vlatković'tir. TDV'nin ifadesiyle kesin Osmanlı hâkimiyeti büyük bir ihtimalle 1468-1469'da gerçekleşti ve 1485 tahriri Livno'yu artık Osmanlı toprağı olarak kaydeder. Bu, Bosna fethinin batı ucunun kapanmasıdır: Livno, düz ova boyunca yalnız otuz altı kilometre ötedeki Venedik topraklarına komşu, tehlikeli bir sınır kasabası hâline geldi ve bu konumunu 1521-1522'de Bosna Valisi Gazi Hüsrev Bey'in Venedik kalelerini almasına kadar korudu.","fethedilen":["Livno (İhlevne)"],"kaynak":"livno","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1512-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Srebrenik banatlığının ilhakı — kuzey Bosna'da Macar hattının ilk kırılması","gun":"1512","yer":"Srebrenik, kuzeydoğu Bosna","yer_id":"Srebrenik","kisiler":"II. Bayezid","d":"Bosna Krallığı 1463'te yıkıldıktan sonra Mátyás Corvin karşı taarruza geçmiş ve krallığın kuzeyinde Osmanlı ilerleyişini durduran iki banatlık kurmuştu: batıda Yayça, kuzeydoğuda Srebrenik. Bunlar Macaristan'ın Bosna'daki ileri savunma hattıydı ve Sava ile Bosna arasındaki koridoru kapatıyorlardı. Srebrenik banatlığı 1512'de ele geçirildi; böylece hattın doğu kanadı çöktü ve İzvornik sancağı kuzeye doğru genişleyebildi. Batı kanadındaki Yayça ise on altı yıl daha dayanacak, ancak Mohaç'tan sonra 1528'de alınabilecekti.","fethedilen":["Srebrenik"],"kaynak":"bosna-hersek","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1402-07-28","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"b":"Ankara bozgununun ardından Eflak Voyvodası Mircea Dobruca'yı yeniden aldı — Silistre, Köstence, Babadağı, İshakçı","gun":"1402 (Ankara Savaşı'nın ardından; gün kaynakta yok)","yer":"Dobruca (Silistre, Köstence, Babadağı, İshakçı)","yer_id":"Silistre","kisiler":"Eflak Voyvodası I. Mircea","d":"Yıldırım Bayezid'in Ankara'da Timur'a yenilmesi Tuna boyundaki Osmanlı hâkimiyetini sarstı. Eflak Voyvodası Mircea bu boşluktan yararlanarak Dobruca'ya yeniden girdi; Silistre, Köstence, Babadağı çevresi ve Tuna kıyısındaki İshakçı Fetret yılları boyunca onun elinde kaldı. Mircea, Çelebi Mehmed'e karşı Mûsâ Çelebi'yi destekledi. Silistre'yi 1418'deki ölümüne kadar tuttu.","kaynak":"silistre","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1416-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Babadağı ve çevresinin Osmanlı'ya geçişi — Mircea ile oğlu Mihail yenildi","gun":"819 (1416)","yer":"Babadağı (Babadag)","yer_id":"Babadağı (Babadag)","kisiler":"Çelebi Sultan Mehmed, Eflak Voyvodası I. Mircea, Mihail","d":"Çelebi Mehmed, Eflak Voyvodası Mircea ile oğlu Mihail'i yendikten sonra Kuzey Dobruca'daki Babadağı ve çevresini Osmanlı hâkimiyetine aldı. Babadağı, Saltuk Baba'nın adını taşıyan ve XIII. yüzyıl Türkmen yerleşimiyle kurulan bir kasabaydı. Çevredeki Silistre, Köstence ve öteki Dobruca kaleleri ise 1419'a kadar Eflak'ta kaldı; yani Babadağı üç yıl Osmanlı toprağından kopuk bir ada (eksklav) olarak görünür.","kaynak":"babadagi","duygu":["🎉"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1419-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Silistre ve Dobruca'nın geri alınışı — Mircea'nın ölümünden sonra","gun":"822 (1419) ilkbaharı","yer":"Silistre, Köstence, İshakçı, Dobruca","yer_id":"Silistre","kisiler":"Çelebi Sultan Mehmed","d":"Eflak Voyvodası Mircea'nın 1418'de ölmesinin ardından Eflak'ta çıkan karışıklık, Çelebi Sultan Mehmed'e Silistre'yi ve Dobruca'yı geri alma fırsatı verdi. 1419 ilkbaharında Silistre, Köstence ve Dobruca'nın büyük kısmı yeniden Osmanlı idaresine girdi; Enisala (Yenisale) ile İshakçı kaleleri onarılıp sınır kalesi (serhat) yapıldı; Dobruca bundan sonra 1878'e kadar Osmanlı'da kaldı.","kaynak":"silistre","duygu":["🎉"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1420-01-01","k":"fetih","etiket":["toprak-kazanc","idari","konu-askeri","konu-idari"],"b":"Aşağı Tuna'nın kapanması — Yergöğü, Turnu ve Orşova'nın ilhakı","gun":"1420","yer":"Yergöğü (Giurgiu), Turnu (Kule), Orşova (Fethülislâm)","yer_id":"Yergöğü (Giurgiu)","kisiler":"Çelebi Sultan Mehmed, Eflak Voyvodası I. Mircea (ö. 1418)","d":"Fetret devri kapandıktan sonra Çelebi Mehmed'in Tuna hattını düzene sokma hamlesi 1420'de meyvesini verdi. Eflak Voyvodası Koca Mircea'nın kendi toprağı üzerinde, masrafını tuz satışıyla karşılayarak yaptırdığı Yergöğü Kalesi bu yıl Osmanlı eline geçti (Dobruca bir yıl önce, 1419 ilkbaharında geri alınmıştı — TDV silistre) ve Tuna'nın sağ kıyısındaki Turnu (Kule/Holovnik) ile Orşova — sonraki adıyla Fethülislâm — ilhak edildi. Böylece nehrin iki yakası birden denetim altına alınmış oldu. Yergöğü'nün önemi coğrafyasındandır: Tuna'nın sol, yani Eflak yakasında kurulmuş bir Osmanlı kalesidir ve karşı kıyıdaki Rusçuk ile aynı geçidin iki ucunu tutar. Osmanlı belgeleri bu ikiliği açıkça yazar — Rusçuk için 'Yergöğü beri yaka', Giurgiu için 'Yergöğü öte yaka' denir. Kale 1427'de Eflaklılar tarafından geri alınacak, 1449'da tekrar Osmanlı denetimine girecek ve Yergöğü kazası Niğbolu sancağına bağlanarak voyvodalık içinde doğrudan idare edilen bir ada hâline gelecekti. Haritada Eflak'ın Tuna boyunun neden koyu renk olduğunun cevabı burada başlar.","fethedilen":["Yergöğü (Giurgiu)"],"kaynak":"yergogu","duygu":["🎉"]}];

