window.OLAYLAR_EK11 = [{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"dis","bolge":3,"t":"1401-01-01","k":"savas","etiket":["yikim","konu-askeri"],"b":"Timur Bağdat'ı ikinci defa işgal etti — şehrin Abbâsî mahalleleri yıkıldı","gun":"1401 (803 h.; ay ve gün kaynakta yok)","yer":"Bağdat, Irâk-ı Arab","yer_id":"Bağdat","kisiler":"Timur, Ahmed Celâyir","d":"Timur Bağdat'ı sekiz yıl arayla iki defa aldı. 1393'teki ilk işgalde şehir fazla zarar görmemişti; 1401'deki ikincisi ise Bağdat'ın kültür hayatına indirilen ikinci ağır darbe sayılır — halk kılıçtan geçirildi, Abbâsî devrinden kalma mahalle ve binaların çoğu tahrip edildi. Celâyirli hükümdarı Ahmed 1405'te şehre dönüp yıkılan surları ve çarşıları onarmaya çalıştıysa da vakit bulamadı; Bağdat 1410'da Karakoyunlu Türkmenleri'nin eline geçti. Bu iki işgal, Ankara Savaşı'na giden yolda Timur'un Osmanlı ve Memlûk sınırlarına ne kadar yaklaştığını gösteren en somut adımlardan biridir.","kaynak":"bagdat","duygu":["⚔️","😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1422-01-01","k":"kayip","etiket":["toprak-kayip","siyaset","konu-askeri","konu-siyasi"],"b":"Cüneyd Bey Aydın-ili'nin başına döndü — Aydınoğulları yeniden müstakil","gun":"1422 (ay ve gün kaynakta yok)","yer":"İzmir, Ayasuluk, Tire, Birgi — Aydın-ili","yer_id":"İzmir","kisiler":"Aydınoğlu Cüneyd Bey, II. Murad, Mustafa Çelebi (Düzmece Mustafa)","d":"Çelebi Mehmed 1414-15'te İzmir'i alıp Cüneyd Bey'i Niğbolu sancak beyliğine göndererek Aydın-ili'ni Osmanlı idaresine bağlamıştı. Cüneyd, Çelebi Mehmed'in ölümünden sonra Bizans'ın taht iddiacısı olarak öne sürdüğü Mustafa Çelebi'nin yanında yeniden sahneye çıktı ve ona vezirlik dahi yaptı. II. Murad, eski beyliğini geri vereceği vaadiyle onu bu ittifaktan ayırdı; Cüneyd de İzmir'e dönüp Ayasuluk'u ele geçirdi ve Aydınoğlu Mustafa Bey'i öldürerek beyliğin başına geçti. Böylece Aydın-ili, Düzmece Mustafa buhranının içinden Osmanlı idaresinden çıkmış olarak doğdu.","kaynak":"aydinogullari","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1426-01-01","k":"fetih","etiket":["siyaset","konu-askeri","konu-siyasi","konu-kisiler"],"b":"Cüneyd Bey ve ailesinin idamı — Aydınoğulları Beyliği'nin sonu","gun":"1426","yer":"İpsili (Sisam karşısı), Aydın-ili","yer_id":"Sisam","kisiler":"Aydınoğlu Cüneyd Bey, II. Murad, Anadolu Beylerbeyi Hamza Bey","d":"Aydın-ili'ne yeniden hâkim olan Cüneyd Bey'in Anadolu beylerini kışkırtması ve Venedik ile temas araması üzerine II. Murad, Anadolu Beylerbeyi Hamza Bey'i onun üzerine gönderdi. Oğlu Kurd Hasan Akhisar yakınlarında yenilip esir düşünce Sisam adası karşısındaki İpsili'ye çekilen Cüneyd, Karamanoğlu'ndan beklediği yardım gelmeyince ve Osmanlı ile birlikte hareket eden Cenevizliler onu denizden ablukaya alınca teslim olmak zorunda kaldı; bütün soyuyla birlikte ortadan kaldırıldı. Aydınoğulları toprakları böylece tamamıyla Osmanlı idaresine girdi.","kaynak":"cuneyd-bey","duygu":["🎉","😔"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"dis","bolge":4,"t":"1502-01-01","k":"siyaset","etiket":["siyaset","savas","konu-askeri","konu-siyasi"],"b":"Erzurum ve Van havzası Safevî'ye geçti — Akkoyunlu'nun kuzey kanadı çöktü","gun":"1502 (ay ve gün kaynakta yok)","yer":"Erzurum, Van, Erciş, Kemah","yer_id":"Erzurum","kisiler":"Şah İsmail, Akkoyunlu Elvend Bey","d":"Şerûr'da Elvend Bey'i yenip 1501 yazında Tebriz'e giren Şah İsmâil, ertesi yıl kuzeybatı istikametinde ilerleyerek Erzurum'dan Van gölü havzasına uzanan hattı hâkimiyeti altına aldı. Akkoyunlu Devleti Uzun Hasan'ın ölümünden sonra zaten taht kavgalarıyla ikiye bölünmüştü: Elvend Bey Azerbaycan ve Diyarbekir'i, amcazadesi Murad ise Irâk-ı Acem ve Fars'ı tutuyordu. Bu bölünme Safevî ilerleyişini kolaylaştırdı; bölge on kayıt hâlinde bir yıl içinde el değiştirdi. Erzurum bundan sonra on altı yıl Safevî elinde kaldı ve Osmanlı hâkimiyetine ancak Çaldıran'dan sonra, 1518-19'da girdi. Bu yıl (1502) Aşkale ve Pasinler (Hasankale), Erzurum bölgesiyle birlikte Akkoyunlu'dan Safevîlere geçti (gün teyitsiz).","kaynak":"akkoyunlular | Yer teyidi (DUNYA-1102 D(b) hücre 5): TDV Erzurum (islamansiklopedisi.org.tr/erzurum)","duygu":["🏛"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"dis","bolge":4,"t":"1503-01-01","k":"siyaset","etiket":["siyaset","savas","konu-askeri","konu-siyasi"],"b":"Murad Bey'in Hemedan yenilgisi: Irâk-ı Acem ve Fars Safevî'ye geçti","gun":"1503 (908 h.; ay ve gün kaynakta yok)","yer":"Hemedan, Isfahan, Şîraz, Kâşân — Irâk-ı Acem ve Fars","yer_id":"Hemedan","kisiler":"Şah İsmail, Akkoyunlu Sultan Murad","d":"Akkoyunlu tahtının ikinci iddiacısı Sultan Murad, Şah İsmâil'e karşı Hemedan yakınlarında yapılan savaşta ağır bir yenilgiye uğradı ve Bağdat'a kaçtı. Bu tek savaşla Irâk-ı Acem, Fars ve Kirman bölgeleri Safevî idaresine girdi; haritada bu bölgeler aynı anda el değiştirir. Akkoyunlu Devleti'nin çözülüşünün en büyük tek adımı budur — Tebriz'in kaybı hânedanı başkentsiz bırakmıştı, Hemedan yenilgisi ise topraksız bıraktı.","kaynak":"safeviler","duygu":["🏛","😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1504-12-06","k":"fetih","etiket":["siyaset","savas","konu-askeri"],"b":"Şah İsmail Yezd'e girdi: Akkoyunlu artığının merkezî İran'daki son kalesi düştü","gun":"6 Aralık 1504 (28 Cemâziyelâhir 910)","yer":"Yezd","yer_id":"Yezd","kisiler":"Şah İsmail","d":"1503 Hemedan yenilgisinden sonra Irâk-ı Acem ve Fars Safevî'ye geçtiği hâlde Yezd, Akkoyunlu hânedanından Bayındırlı Murad Bey'in elinde ayrı kalmıştı. Şehir bir aylık kuşatmayla düştü ve merkezî İran'daki son Akkoyunlu adası kapandı. TDV'nin kaydı: \"Şah İsmâil 28 Cemâziyelâhir 910 (6 Aralık 1504) tarihinde bir aylık bir kuşatmanın ardından şehre girdi.\"","kaynak":"yezd · sah-ismail","duygu":["🏛"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"dis","bolge":4,"t":"1507-01-01","k":"siyaset","etiket":["siyaset","savas","konu-askeri","konu-siyasi"],"b":"Şah İsmail'in Diyarbekir seferi: Akkoyunlu'nun son merkezleri düştü","gun":"1507 (912-913 h.; ay ve gün kaynakta yok)","yer":"Diyarbekir, Âmid, Mardin, Urfa, Harput, Siverek","yer_id":"Diyarbakır","kisiler":"Şah İsmail, Akkoyunlu hânedanı","d":"Azerbaycan ve İran platosunu ele geçiren Şah İsmâil 1507'de batıya, Akkoyunlu hânedanının doğduğu Diyarbekir bölgesine yöneldi. Âmid'den Mardin'e, Urfa'dan Harput'a uzanan hat iki hamlede Safevî idaresine girdi ve Akkoyunlular fiilen ortadan kalktı. Bu sefer aynı zamanda Safevî sınırını ilk defa Osmanlı ve Memlûk sınırlarına dayadı; Çaldıran'a giden gerilimin coğrafî zemini böyle kuruldu.","kaynak":"safeviler","duygu":["🏛"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"dis","bolge":4,"t":"1508-01-01","k":"siyaset","etiket":["siyaset","savas","konu-askeri","konu-siyasi"],"b":"Bağdat'ın Safevî'ye geçişi — Irâk-ı Arab el değiştirdi","gun":"1508 (914 h.; ay ve gün kaynakta yok)","yer":"Bağdat, Kerbelâ, Necef, Musul — Irâk-ı Arab","yer_id":"Bağdat","kisiler":"Şah İsmail","d":"Hemedan yenilgisinden sonra Bağdat'a sığınan Akkoyunlu Sultan Murad'ın ardından Şah İsmâil 1508'de Irâk-ı Arab'a girdi ve Bağdat'ı aldı. Kerbelâ ve Necef'teki türbelerin Safevî idaresine geçmesi, hareketin mezhebî iddiası bakımından Tebriz'in alınması kadar önemliydi. Haritada Irâk-ı Arab aynı gün el değiştirir; bu, çözülüşün son ve en geniş coğrafî adımıdır. Bağdat 1534'te Kanûnî'nin Irakeyn Seferi'ne kadar Safevî elinde kaldı.","kaynak":"safeviler","duygu":["🏛"]},{"dunya":2,"bolge_onem":5,"puan_s":"v2","tur":"savas","bolge":4,"t":"1510-12-02","k":"savas","etiket":["savas","siyaset","konu-askeri","konu-siyasi"],"kapsam":"dis","onem":4,"b":"Merv Savaşı: Özbekler ağır yenilgiye uğradı, Merv ve Herat alındı","gun":"1510 sonu","yer":"Merv, Herat — Horasan","yer_id":"Merv (Mari)","kisiler":"Şah İsmail, Şeybânî Han (Muhammed Şeybânî)","d":"Batıda Akkoyunlu mirasını tamamlayan Şah İsmâil doğuya, Horasan'a yürüdü ve Merv önlerinde Özbekler'i ağır bir yenilgiye uğrattı; Şeybânî Han savaş meydanında öldü. Merv ve Herat Safevî hâkimiyetine girdi ve Safevî Devleti Fırat'tan Ceyhun'a uzanan sınırlarına kavuştu. Böylece 1501 yazında Tebriz'e girişle başlayan süreç dokuz yılda tamamlanmış oldu: Akkoyunlu mirası bütünüyle Safevî idaresine geçti ve Osmanlı Devleti doğusunda kendi büyüklüğünde ikinci bir devletle komşu hâle geldi.","kaynak":"safeviler","duygu":["⚔️","😔"]},{"onem":5,"dunya":3,"bolge_onem":4,"puan_s":"v2","bolge":2,"t":"1581-04-16","k":"siyaset","etiket":["siyaset","diplomasi","konu-siyasi","konu-diplomasi"],"kapsam":"dis","b":"İberya Birliği: Portekiz tacı İspanya kralına geçti","gun":"16 Nisan 1581","yer":"Tomar — Portekiz","kisiler":"II. Felipe (Portekiz kralı I. Filipe), Kardinal Kral Henrique","d":"Kardinal Kral Henrique'nin vârissiz ölümüyle açılan veraset kavgası Alcântara Muharebesi'nde (25 Ağustos 1580) İspanya lehine kapandı ve Tomar'da toplanan Portekiz Cortes'i 16 Nisan 1581'de II. Felipe'yi Portekiz kralı olarak tanıdı. Tomar şartlarına göre Portekiz kendi kurumlarını, parasını ve dilini koruyacak, yönetime yalnız Portekizliler atanacak, Madrid'de ayrı bir Portekiz konseyi bulunacaktı — yani birleşme kişisel birlikti, ilhak değil.","duygu":["🏛"],"yer_kon":[39.6,-8.42]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","bolge":1,"t":"1640-12-01","k":"siyaset","etiket":["siyaset","toprak-kayip","konu-askeri","konu-siyasi"],"kapsam":"dis","b":"Restauração: Portekiz bağımsızlığını geri aldı","gun":"1 Aralık 1640","yer":"Lizbon","yer_id":"Lizbon","kisiler":"IV. João (Braganza Dükü), Kont-Dük Olivares","d":"Katalonya isyanının İspanya'yı meşgul ettiği günlerde Lizbon'da bir grup soylu saraya baskın yaparak İspanyol idaresini devirdi ve Braganza Dükü'nü IV. João adıyla kral ilan etti. Altmış yıllık İberya Birliği böylece sona erdi; ancak Sebte İspanya'da kalmayı seçti ve bu 1668 Lizbon Antlaşması'yla tanındı. Portekiz'in Habsburg savaşlarına eklemlendiği bu pencere Asya'daki kayıplarının da çerçevesidir: Hürmüz 1622'de, Malaka 1641'de, Kolombo 1656'da elden çıktı; Tanca ile Bombay ise bağımsızlığın bedeli olarak İngiltere'ye verildi. Kaynak: Britannica, History of Portugal — Restoration.","duygu":["🏛"],"kaynak":"encyclopedia.com 'Portugal, Restoration of 1640' — «The revolt of December 1640 resulted in the acclamation of João IV»"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1539-02-24","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Zebîd'in Osmanlı hâkimiyetine kesin girişi","gun":"24 Şubat 1539 (5 Şevval 945)","kesinlik":"gun","yer":"Zebîd — Yemen","yer_id":"Zebîd","kisiler":"Hadım Süleyman Paşa","d":"Diu kuşatmasını 5 Kasım 1538'de kaldıran donanma dönüş yolunda Yemen kıyısına uğradı ve Zebîd kesin olarak Osmanlı idaresine bağlandı; Hadım Süleyman Paşa şehirden 10 Mart 1539'da ayrılıp 1 Nisan'da Cidde'ye vardı. Şehir 1517'den beri eski Memlûk beylerinin elinde Osmanlı adına yönetiliyordu; bu tarihle doğrudan idareye geçti.","duygu":["🎉"],"kaynak":"TDV İslâm Ansiklopedisi, 'Süleyman Paşa, Hadım' (islamansiklopedisi.org.tr/suleyman-pasa-hadim); TDV 'Zebîd' (945/1539) — «Zebîd hâkimi Nâhudâ Ahmed Bey'i 5 Şevval 945'te (24 Şubat 1539) bir divan toplantısı sırasında öldürterek»"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","bolge":1,"t":"1662-01-30","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"kapsam":"dis","b":"Tanca İngiltere'ye devredildi","gun":"30 Ocak 1662","yer":"Tanca — Fas","yer_id":"Tanca","kisiler":"II. Charles, Catherine de Braganza, Peterborough Kontu","d":"Portekiz'in bağımsızlık savaşında İngiliz desteğini sağlamak için yapılan evlilik antlaşmasının (23 Haziran 1661) ikinci maddesi Tanca'yı Catherine de Braganza'nın çeyizi olarak İngiltere'ye bırakıyordu. Sandwich Kontu'nun filosu 29 Ocak 1662'de demirledi ve ertesi gün Peterborough Kontu'nun töreniyle resmî devir yapıldı. İngilizler şehri 1684'te terk edecekti.","duygu":["🤝"],"kaynak":"TDV İslâm Ansiklopedisi, TANCA (islamansiklopedisi.org.tr/tanca) — ««1661’de İngiltere Kralı II. Charles’in Braganza prensesiyle evliliği sonucu çeyiz olarak İngiltere’ye intikal etti.»»"},{"dunya":2,"bolge_onem":5,"puan_s":"v2","bolge":4,"t":"1747-06-20","kaynak":"Encyclopaedia Iranica, Afsharids (https://www.iranicaonline.org/articles/afsharids-dynasty/) — «assassinated by his Iranian officers on 11 Jomādā II 1160/20 June 1747» (KASA SALI kuyruğu 20; KASA PAZAR 4 Kasım 2026) | Yer teyidi (DUNYA-1102 D(b) hücre 5): TDV İslâm Ansiklopedisi, islamansiklopedisi.org.tr/nadir-sah--iran ; revan","k":"siyaset","etiket":["siyaset","suikast","konu-siyasi","konu-kisiler"],"kapsam":"dis","onem":4,"b":"Nâdir Şah'ın öldürülmesi — Afşar hâkimiyetinin dağılışı","gun":"20 Haziran 1747","yer":"Fethâbâd, Horasan","kisiler":"Nâdir Şah Afşar","d":"Safevî tahtını sona erdirip 1736'da kendi adına saltanat ilân eden, Hindistan seferiyle Delhi'ye kadar giden ve Osmanlı ile üç savaş yapıp 1746 Kerden Antlaşması'yla barışan Nâdir Şah, kendi muhafızları tarafından çadırında öldürüldü. Ardından İran tek elden yönetilemedi: Horasan'da Afşar kalıntısı, güneyde Zend, kuzeyde yükselen Kaçar kırk dokuz yıl boyunca ülkeyi paylaştı. Osmanlı doğu sınırı bu dağınıklık sayesinde uzun süre sakin kaldı. Nâdir Şah 20 Haziran 1747'de öldürüldü; TDV'ye göre Revan Hanlığı aynı yıl (1747) kuruldu, gün teyitsiz.","duygu":["🏛"],"yer_kon":[37.1,58.5]},{"dunya":2,"bolge_onem":4,"puan_s":"v2","bolge":4,"t":"1796-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi","konu-hanedan"],"kapsam":"dis","onem":4,"b":"Kaçar hânedanının İran'a hâkim oluşu","gun":"1796 (gün kaynakta yok; devlet dizini bu tarihi Afşar'ın bitişi olarak taşıyor)","yer":"Tahran","yer_id":"Tahran","kisiler":"Ağa Muhammed Şah Kaçar","d":"Kaçar aşiretinin reisi Ağa Muhammed Han, Zend hâkimiyetini yıkıp Horasan'daki son Afşar direncini de kırarak İran'ı yeniden tek elde topladı ve Tahran'ı başkent yaptı. Kırk dokuz yıllık parçalanma dönemi böylece kapandı; bundan sonra Osmanlı'nın doğu komşusu 1923'e kadar Kaçar İran'ı olacaktı. Meşhed, TDV İslâm Ansiklopedisi'ne göre 1796'da Ağa Muhammed Şah'ın önünde Afşar hükümdarı Şâhruh tarafından karşılandı ve Kaçar hâkimiyetine girdi (gün kaynakta yok).","duygu":["🏛"],"kaynak":"TDV İslâm Ansiklopedisi, 'Kaçarlar' (islamansiklopedisi.org.tr/kacarlar) — «“şehinşahlık” tacını giyerek adına hutbe okuttu ve para kestirdi (1796).» | Yer teyidi (DUNYA-1102 D(b) hücre 11): TDV İslâm Ansiklopedisi, 'AVŞARLILAR' (https://islamansiklopedisi.org.tr/avsarlilar); 'KAÇARLAR' (https://islamansiklopedisi.org.tr/kacarlar); 'MEŞHED' (https://islamansiklopedisi.org.tr/meshed--iran)"}];

