window.OLAYLAR_EK12 = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1560-03-12","k":"savas","etiket":["savas","konu-askeri"],"b":"Haçlı donanması Cerbe'yi işgal etti — Turgut Paşa'nın üssü elden çıktı","gun":"12 Mart 1560 (14 Cemâziyelâhir 967)","yer":"Cerbe (Djerba), Trablusgarp","yer_id":"Cerbe (Djerba)","kisiler":"Turgut Paşa, Piyâle Paşa","d":"İspanya, Papalık, Malta, Ceneviz ve Floransa gemilerinden kurulu Haçlı donanması, Turgut Reis'in 1551'den beri akın üssü olarak kullandığı Cerbe'yi hedef aldı. Fırtınalar ve salgın yüzünden ada önlerine ancak 1560 yılı başlarında ulaşabildi; 12 Mart 1560'ta adayı işgal edip bir kale inşa etti. Haberi alan Piyâle Paşa 28 Mart'ta 120 kadırgalık donanmasıyla İstanbul'dan yola çıktı. İşgal uzun sürmedi: Osmanlı donanması mayısta Cerbe önünde müttefikleri yendi, kale de temmuz sonunda geri alındı. Bu sefer, Preveze'den sonra Akdeniz'de Osmanlı üstünlüğünü pekiştiren ikinci büyük deniz harekâtının başlangıcıdır.","kaynak":"cerbe + piyale-pasa — TDV piyale-pasa birebir: 'İspanya yönetimindeki müttefik hıristiyan donanması 14 Cemâziyelâhir 967’de (12 Mart 1560) Cerbe adasını işgal etti. Bunun üzerine Piyâle Paşa, 120 kadırgadan oluşan donanmasıyla 1 Receb 967’de (28 Mart 1560) İstanbul’dan yola çıktı.' · TDV cerbe: '1560 yılı başlarında' (gün vermiyor). · Düzeltme: t: 1560-01-01 → 1560-03-12; önceki metindeki 'beş ay içinde' ifadesi çıkarıldı (işgal 12 Mart, kale 30 Temmuz).","duygu":["⚔️","😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1560-07-30","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Cerbe kalesinin düşüşü — adanın Osmanlı idaresine geçişi","gun":"30 Temmuz 1560","yer":"Cerbe (Djerba)","yer_id":"Cerbe (Djerba)","kisiler":"Piyâle Paşa, Turgut Paşa","d":"Piyâle Paşa'nın 14 Mayıs 1560'taki deniz zaferinden sonra Haçlı kuvvetleri adada inşa ettikleri kaleye kapandı; Trablusgarp beylerbeyi Turgut Paşa'nın kuvvetleri karadan kuşattı. İki ay süren muhasara 30 Temmuz 1560'ta kalenin düşmesiyle bitti ve ada Trablusgarp beylerbeyiliğine bağlandı. Deniz zaferi ile kalenin fethi arasında yetmiş yedi gün vardır; ada 14 Mayıs'ta değil 30 Temmuz'da fiilen el değiştirmiştir.","kaynak":"cerbe","duygu":["🎉","😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"dis","bolge":5,"t":"1527-09-23","k":"kayip","etiket":["toprak-kaybi","konu-askeri"],"b":"Ferdinand Budin'i ele geçirdi — Szapolyai başşehirden çıkarıldı","gun":"23 Eylül 1527","yer":"Budin (Buda), Peşte","yer_id":"Aquincum-Óbuda-Pest","kisiler":"I. Ferdinand, János Szapolyai, Kanûnî Sultan Süleyman","d":"Mohaç'tan sonra Macar tahtında iki kral çıkmıştı: soyluların bir kısmı János Szapolyai'yi, bir kısmı Habsburg Ferdinand'ı seçmişti. Ferdinand 1527'de Budin'i ele geçirip Szapolyai'yi başşehirden çıkardı; Szapolyai Sultan Süleyman'dan yardım istedi. Bu, 1529 Viyana seferinin ilk hedefinin Budin olmasının sebebidir.","kaynak":"TDV suleyman-i AYNEN: '23 Eylül 1527'de Ferdinand, Szapolyai'yi Budin'den çıkarınca içerideki ağır krize rağmen Kanûnî Sultan Süleyman ve İbrâhim Paşa bütün dikkatlerini buraya yöneltti.' · TDV budin AYNEN: '1527 Ağustosunda Buda'yı ele geçiren Ferdinand'a karşı János Szapolyai Sultan Süleyman'dan yardım istedi.'"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"vassal","kapsam":"ic","t":"1537-01-01","k":"vassal","etiket":["toprak-kazanc","siyaset","konu-askeri","konu-siyasi"],"b":"Barbaros'un Ege adaları seferi — Nakşa Dükalığı Osmanlı kontrolüne girdi","gun":"944-945 (1537-1538)","yer":"Nakşa (Naxos), Paros, Değirmenlik (Milos), Kimolos, Sire (Syros), Nio (İos), Santorini ve çevre adalar","yer_id":"Nakşa","kisiler":"Barbaros Hayreddin Paşa","d":"1207'den beri Venedik vesâyetinde Latin dükleri tarafından yönetilen Nakşa Dükalığı, Barbaros Hayreddin Paşa'nın adalar seferiyle Osmanlı kontrolü altına girdi. Adanın statüsüne dokunulmadı; dükalık Osmanlı'ya tâbi olarak sürdü ve 1540 Osmanlı-Venedik antlaşmasıyla hâkimiyet hakkı resmen Osmanlılar'a devredildi.","kaynak":"TDV naksa AYNEN: 'Nakşa ve civarındaki adalar, 944-945 (1537-1538) yıllarında Barbaros Hayreddin Paşa'nın adalar seferiyle Osmanlı kontrolü altına girdi.' · '1540'taki Osmanlı-Venedik antlaşmasıyla hâkimiyet hakkı resmen Osmanlılar'a devredildi.' · 'Ancak adanın statüsüne dokunulmadı ve düklük Yasef Nasi'ye verildi (974/1566).'"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1913-08-31","k":"siyaset","kapsam":"ic","etiket":["siyaset","konu-siyasi"],"b":"Gümülcine merkezli Garbî Trakya Hükûmet-i Muvakkatesi ilân edildi","gun":"31 Ağustos 1913","yer":"Gümülcine, Batı Trakya","yer_id":"Gümülcine","kisiler":"Müderris Sâlih Efendi","d":"Bükreş Antlaşması (10 Ağustos 1913) Batı Trakya'yı Bulgaristan'a bırakınca bölgenin Türk halkı Gümülcine merkezli geçici bir hükümet ilân etti; Dedeağaç'ın alınmasından sonra hükümet bağımsızlığını 'Garbî Trakya Hükûmet-i Müstakillesi' adıyla duyurdu. Büyük devletlerin müdahalesiyle Osmanlı hükümeti onu desteklemedi; 29 Eylül 1913 İstanbul Antlaşması Batı Trakya'yı Bulgarlar'a bıraktı ve hükümet 25 Ekim 1913'e kadar ancak elli yedi gün yaşadı.","kaynak":"TDV bati-trakya AYNEN: '31 Ağustos 1913'te merkezi Gümülcine olmak üzere Garbî Trakya Hükûmet-i Muvakkatesi ilân edildi.' · '25 Ekim 1913'e kadar Bulgaristan'a teslimi şart koşulan Batı Trakya'da Garbî Trakya Hükûmet-i Müstakillesi varlığını ancak elli yedi gün sürdürebildi.'"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1814-02-04","k":"siyaset","kapsam":"dis","etiket":["siyaset","konu-siyasi"],"b":"Danzig'de Rus-Prusya ikili iktidarı sona erdi — Napolyon'un serbest şehri Prusya'ya döndü","gun":"4 Şubat 1814","yer":"Danzig (Gdańsk)","yer_id":"Gdansk","kisiler":"I. Aleksandr","d":"Tilsit barışıyla (9 Temmuz 1807) Prusya'dan ayrılıp Fransız koruması altında serbest şehir yapılan Danzig'i Napolyon'un kuvvetleri 1813 kuşatmasından sonra terk etti. 2 Ocak – 4 Şubat 1814 arasında şehirde Rus-Prusya ikili iktidarı sürdü; Çar Aleksandr'ın Danzig ve Vistül ağzını alma planından vazgeçmesiyle şehir Prusya idaresine geçti.","kaynak":"Gedanopedia (Encyklopedia Gdańska), 'WOLNE MIASTO GDAŃSK, 1807–1815' AYNEN: 'Po opuszczeniu przez wojska napoleońskie miasta na krótko, między 2 stycznia a 4 lutego 1814, doszło w nim do dwuwładzy.' · 'Sytuację wyjaśniło wycofanie się z końcem stycznia 1814 cara Aleksandra I z planów zajęcia przez Rosję Gdańska i ujścia Wisły.' · kuruluş: '… traktatów … francusko-pruskiego z 9 VII 1807 zawartych w Tylży …'"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1920-11-15","k":"siyaset","kapsam":"dis","etiket":["siyaset","konu-siyasi"],"b":"Danzig Serbest Şehri Milletler Cemiyeti koruması altında kuruldu","gun":"15 Kasım 1920","yer":"Danzig (Gdańsk)","yer_id":"Gdansk","d":"Versay Antlaşması'yla Almanya'dan ayrılan Danzig, 10 Ocak 1920'den itibaren müttefik büyük devletlerin geçiş idaresinde kaldı; 15 Kasım 1920'de Milletler Cemiyeti'nin koruması altında Polonya ile gümrük birliği içindeki serbest şehir olarak kuruldu.","kaynak":"Gedanopedia (Encyklopedia Gdańska), 'WOLNE MIASTO GDAŃSK, 1920–1939' AYNEN: 'Od 10 I do 15 XI 1920, w okresie przejściowym, II WMG znajdowało się pod zarządem głównych mocarstw sprzymierzonych.' · '9 I 1920 podpisano protokół przejęcia Gdańska przez aliantów, w wyniku którego Niemcy straciły wszelkie prawa na jego obszarze.'"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1815-05-03","k":"siyaset","kapsam":"dis","etiket":["siyaset","diplomasi","konu-diplomasi"],"b":"Viyana'da Krakov serbest, bağımsız ve tarafsız şehir ilân edildi","gun":"3 Mayıs 1815","yer":"Krakov","yer_id":"Krakov","d":"Viyana Kongresi'nde Rusya, Avusturya ve Prusya, Krakov şehrini çevresiyle birlikte üç devletin koruması altında serbest bir devlet yaptı; Viyana Nihai Senedi bu düzeni tescil etti.","kaynak":"P. Cichoń, 'The Free City of Kraków in the Regional Security Policies of its Neighbouring States', Krakowskie Studia z Historii Państwa i Prawa 12/4 (2019), s. 523-535, doi:10.4467/20844131KS.19.025.11643: Avusturya, Prusya ve Rusya'nın 'additional treaty signed on 3 May 1815' ile Krakov serbest, bağımsız ve tarafsız şehir oldu ; Encyclopædia Britannica 1911, 'Cracow' (Wikisource) AYNEN: 'by the Final Act of the congress signed at Vienna in 1815, \"the town of Cracow, with its territory, is declared to be for ever a free, independent and strictly neutral city, under the protection of Russia, Austria and Prussia.\"' · gün: Hertslet No. 14 (künyeden)"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1846-11-11","k":"siyaset","kapsam":"dis","etiket":["siyaset","diplomasi","konu-diplomasi"],"b":"Krakov Serbest Şehri kaldırıldı, Avusturya'ya katıldı","gun":"11 Kasım 1846","yer":"Krakov","yer_id":"Krakov","d":"Şubat 1846 Krakov ayaklanmasını bahane eden Rusya, Avusturya ve Prusya, Viyana'daki konferansta serbest şehri kaldırıp Avusturya topraklarına katmaya karar verdi; İngiltere ve Fransa'nın itirazları sonuç vermedi.","kaynak":"Tomasz Kargol, 'Włączenie Krakowa do Austrii w 1846 r. w świetle wybranych tytułów prasy austriackiej i niemieckiej', Historia Slavorum Occidentis 23 (2023), s. 179 vd., doi:10.15804/hso230306 — «manifesty cesarza austriackiego Ferdynanda I z 11 listopada 1846 r. i feldmarszałka Heinricha Castiglionego z 16 listopada 1846 r.»"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1893-01-01","k":"fetih","kapsam":"dis","etiket":["askeri","konu-askeri"],"b":"Bornu, Râbih b. Zübeyr'in hâkimiyetine girdi","gun":"1893","yer":"Bornu (Kukava, Dikeo)","yer_id":"Dikva (Dikeo)","kisiler":"Râbih b. Zübeyr","d":"Bagirmi ve Vedây'ı sarsan Sudanlı savaş beyi Râbih b. Zübeyr Bornu'yu ele geçirdi; 1896'ya kadar ülkenin tamamını alıp Dikeo'yu merkez edindi.","kaynak":"TDV bornu AYNEN: '… Bornu, Bagirmi Sultanı Râbih b. Zübeyir'in hâkimiyetine girdi (1893).' · '1896'ya kadar ülkenin tamamını ele geçiren ve Dikeo'yu merkez edinen Râbih 1900'de Fransız sömürge ordusu tarafından mağlûp edilerek öldürülünce yerine oğlu hâkimiyetini devam ettirmek istedi, fakat Fransızlar karşısında tutunamadı.'"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"savas","bolge":1,"t":"1900-04-22","k":"savas","kapsam":"dis","etiket":["savas","konu-askeri"],"b":"Râbih b. Zübeyr Fransızlara yenilip öldürüldü — Bornu'daki hâkimiyeti çözüldü","gun":"22 Nisan 1900 (Kusseri muharebesi)","yer":"Bornu","yer_id":"Dikva (Dikeo)","kisiler":"Râbih b. Zübeyr","d":"Fransız sömürge ordusuna yenilen Râbih öldürüldü; oğlu hâkimiyeti sürdürmek istediyse de tutunamadı ve Bornu 1902'de Fransa, İngiltere ve Almanya arasında paylaşıldı.","kaynak":"TDV bornu AYNEN: '… Râbih 1900'de Fransız sömürge ordusu tarafından mağlûp edilerek öldürülünce yerine oğlu hâkimiyetini devam ettirmek istedi, fakat Fransızlar karşısında tutunamadı.' · TDV cad AYNEN: '… Dikoa'daki (Dikwa) savaşta esir düştü ve öldürüldü (1900).'"}];

