window.OLAYLAR_EK13 = [{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1569-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Uluç Ali Paşa'nın Tunus'u alışı — Hafsî-İspanyol düzeninin sonu","gun":"1569","yer":"Tunus, Beja — İfrîkıye","yer_id":"Tunus","kisiler":"Uluç (Kılıç) Ali Paşa, III. Mevlây Ahmed","d":"Şarlken 1535'te Tunus'u aldığında şehri kendisi yönetmemiş, Hafsî sultanı Mevlây Hasan'ı tahta geri oturtmuştu; TDV'nin ifadesiyle Tunus şehri \\\"1569'daki Osmanlılar'ın ikinci müdahalesine kadar İspanyollar'ın himayesinde ve III. Mevlây Ahmed'in idaresinde\\\" kaldı. 27 Haziran 1568'de Cezayir beylerbeyiliğine getirilen Uluç Ali karadan Tunus üzerine yürüdü, Beja'da Hafsî sultanını yenerek şehre girdi; Mevlây Ahmed İspanyol presidiosu Halkulvâdî'ye sığındı. Böylece körfez ikiye bölündü — şehir Osmanlı, liman kalesi İspanyol — ve bu bölünme dört yıl sürdü.","kaynak":"tunus","duygu":["🎉"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1573-10-10","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"b":"Don Juan de Austria'nın Tunus'u geri alışı — İnebahtı'nın karadaki tek karşılığı","gun":"10 Ekim 1573","yer":"Tunus, Halkulvâdî","yer_id":"Tunus","kisiler":"Don Juan de Austria, Kılıç Ali Paşa, Ramazan Paşa, Haydar Paşa","d":"İnebahtı'dan (1571) sonra Kutsal İttifak dağıldığı hâlde İspanya tek başına Kuzey Afrika'ya yüklendi: TDV'nin ifadesiyle \"10 Ekim 1573'te İspanyollar, Tunus'ta kontrolü ele geçirmek amacıyla yeni bir harekâta giriştiler. Tunus'u alıp burada 8000 asker bıraktılar.\" Don Juan de Austria kumandasındaki bu harekât, İnebahtı zaferinin karada karşılık bulduğu tek yerdir; ne var ki kalıcı olmadı ve şehir on bir ay sonra geri alındı. İşgalin devirdiği şey kurulmuş bir Osmanlı idaresiydi: 2 Zilhicce 980'de (5 Nisan 1573) Tunus kumandanı Kılıç Ali Paşa, kaymakamı Ramazan Paşa, beylerbeyi Haydar Paşa idi.","kaynak":"tunus","duygu":["😔"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1471-08-24","k":"fetih","etiket":["toprak-kazanc","konu-askeri","konu-imar","konu-ulastirma"],"kapsam":"dis","b":"Arzila'nın Portekiz tarafından alınışı — Fas kıyısında ikinci köprübaşı","gun":"24 Ağustos 1471","yer":"Arzila (Asîlâ) — Fas","kisiler":"V. Afonso (Portekiz kralı)","d":"V. Afonso 30.000 kişilik bir kuvvet ve 400 parçalık donanmayla bizzat Fas kıyısına çıktı ve Vattâsî idaresindeki Arzila'yı 24 Ağustos 1471'de aldı. Şehrin düşmesi Tanca'nın direncini kırdı; Tanca dört gün sonra, 28 Ağustos'ta savaşsız teslim oldu. Portekiz böylece Sebte (1415) ve Kasrüssagīr'den (1458) sonra Fas'ın Atlas kıyısında üçüncü ve dördüncü mevziisini kurdu; kral bu seferden sonra unvanına \"Afrika'nın efendisi\" ibaresini ekletti.","duygu":["🎉"],"yer_id":"Arzila (Asilah)","kaynak":"Les croisades marocaines, frontières d’outre-mer de la Reconquista, OpenEdition Books (IHEAL), bölüm 2 (books.openedition.org/iheal/2154) — «Arzila tomba le 24 août.»"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"vassal","bolge":1,"t":"1488-01-01","k":"vassal","etiket":["toprak-kazanc","konu-askeri","konu-siyasi"],"kapsam":"dis","b":"Safi'nin Portekiz nüfuzuna girmesi","gun":"1488","yer":"Safi (Asfi) — Fas Atlas kıyısı","yer_id":"Safi (Asfi)","d":"Atlas kıyısının en işlek tahıl ve balıkçılık limanı olan Safi, 1488'de Portekiz nüfuzuna girdi; şehir bir süre yerli yöneticiler eliyle Portekiz himayesinde yönetildi ve 1508'de doğrudan işgal edildi. Kaynaklar bu iki aşamayı farklı ağırlıklandırdığı için başlangıç tarihi 1488 ile 1508 arasında değişir; ikisi de aynı sürecin uçlarıdır. Safi elli üç yıl Portekiz elinde kaldı ve 1541'de Agadir'in düşüşünün ardından boşaltıldı.","duygu":["🎌"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"kurulus","bolge":1,"t":"1505-01-01","k":"kurulus","etiket":["toprak-kazanc","konu-askeri","konu-siyasi"],"kapsam":"dis","b":"Santa Cruz do Cabo de Gué'nin kuruluşu — Agadir'de Portekiz kalesi","gun":"1505 (gün ve ay kaynakta yok; taca devir 1513)","yer":"Agadir (Santa Cruz do Cabo de Gué) — Sûs kıyısı","yer_id":"Agadir","kisiler":"João Lopes de Sequeira","d":"Sûs kıyısında, o güne dek Portekiz'in ulaşmadığı bir noktada özel teşebbüsle kurulan Santa Cruz do Cabo de Gué kalesi 1505'te inşa edildi ve 1513'te Portekiz tacına devredildi. Kale, Sûs vadisinin şeker ve altın ticaretini denetleyerek Merakeş'in güneybatı çıkışını kapatıyordu; bu yüzden Sa'dî hareketinin ilk büyük hedefi oldu. 1533'teki kuşatma püskürtüldü, 1541'deki ise başarıya ulaştı ve Portekiz'in Fas'taki çöküşünü başlattı.","duygu":["🌱"],"kaynak":"J. Correia & A. Lopes, 'Azemmour, Morocco: early sixteenth-century Portuguese defences' (repositorium.uminho.pt, hakemli yayın), s.3 — ««castles were built immediately, such as in Santa Cruz do Cabo de Guer (Agadir) in 1505; in Mogador (Essaouira) in 1506 ... in Mazagão (El Jadida), in 1514»»"},{"onem":3,"dunya":2,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1513-09-03","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"kapsam":"dis","b":"Azemmûr'un alınışı — Ümmürrebî' ağzının denetimi","gun":"3 Eylül 1513","yer":"Azemmûr — Ümmürrebî' nehri ağzı, Fas","yer_id":"Azemmûr","kisiler":"Jaime (Braganza Dükü)","d":"Braganza Dükü Jaime kumandasındaki Portekiz ordusu Ümmürrebî' nehrinin ağzındaki Azemmûr'a 3 Eylül 1513'te direnişle karşılaşmadan girdi. Şehrin alınması hem nehir ağzının hem de iç bölgeye açılan tahıl yolunun denetimini verdi ve ertesi yıl 12 km güneybatısında Mazagan kalesinin kurulmasının önünü açtı. Azemmûr yirmi sekiz yıl Portekiz elinde kaldı.","duygu":["🎉"],"kaynak":"J. Correia & A. Lopes, 'Azemmour, Morocco: early sixteenth-century Portuguese defences' (repositorium.uminho.pt, hakemli yayın), s.4 — ««the first military expedition against Azemmour failed, only to succeed five years later in 1513, on September 3rd.»»"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"kurulus","bolge":1,"t":"1514-01-01","k":"kurulus","etiket":["toprak-kazanc","konu-askeri","konu-siyasi"],"kapsam":"dis","b":"Mazagan kalesinin kurulması — Fas'ta en uzun kalacak Portekiz mevzii","gun":"1514 yazı (gün kaynakta yok; kale 1541-42'de yeniden ve çok daha güçlü inşa edildi)","yer":"Mazagan (el-Cedîde) — Fas Atlas kıyısı","d":"Azemmûr'un alınmasının ertesi yılı, 1514 yazında kıyıda Mazagan hisarı inşa edildi. 1541'deki genel çöküşten sonra Portekiz, Fas'taki bütün mevzilerini bırakırken Mazagan'ı bırakmadı; tersine kaleyi İtalyan tarzı burçlarla baştan yaptırdı ve şehir iki yüz elli beş yıl boyunca elde tutuldu. 1562'deki büyük kuşatma da püskürtüldü. Mazagan, Portekiz'in Fas'taki son mevzii olarak 1769'da boşaltılacaktı.","duygu":["🌱"],"yer_id":"Mazagan (El Jadida)","kaynak":"J. Correia & A. Lopes, 'Azemmour, Morocco: early sixteenth-century Portuguese defences' (repositorium.uminho.pt, hakemli yayın), s.3, s.13 — ««in Mazagão (El Jadida), in 1514» / «from early 1514»»"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1541-03-12","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"kapsam":"dis","b":"Agadir'in düşüşü — Sa'dîler'in Portekiz'i Fas'tan söküşü başlıyor","gun":"12 Mart 1541 (kuşatma 16 Şubat 1541'de başladı)","yer":"Agadir (Santa Cruz do Cabo de Gué) — Sûs","yer_id":"Agadir","kisiler":"Muhammed eş-Şeyh (Sa'dî sultanı), Guterre de Monroy (vali)","d":"Sa'dî sultanı Muhammed eş-Şeyh 16 Şubat 1541'de Santa Cruz kalesini kuşattı ve 12 Mart'ta zaptetti; vali Guterre de Monroy dahil altı yüz kadar Portekizli esir düştü.","kaynak":"fas","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1541-10-01","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"kapsam":"dis","b":"Safi ve Azemmûr'un boşaltılması — Portekiz Atlas kıyısından çekiliyor","gun":"Ekim 1541 (tahliye Eylül-Ekim'de tamamlandı; gün kaynakta yok)","yer":"Safi (Asfi), Azemmûr — Fas Atlas kıyısı","yer_id":"Safi (Asfi)","kisiler":"III. João (Portekiz kralı), Muhammed eş-Şeyh","d":"Agadir'in 12 Mart 1541'de düşmesi ve Fas sultanıyla umulan ittifakın kurulamaması üzerine III. João, Atlas kıyısındaki iki büyük mevziin boşaltılmasını emretti; Safi ve Azemmûr'un tahliyesi 1541 sonbaharında, Eylül-Ekim aylarında tamamlandı. Böylece tek yılda üç mevzi elden çıktı ve Portekiz'in Fas kıyısındaki elli yıllık yayılması tersine döndü; geriye Sebte, Tanca, Arzila, Kasrüssagīr ve yeni tahkim edilen Mazagan kaldı.","kaynak":"fas","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1549-01-01","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"kapsam":"dis","b":"Arzila'nın boşaltılması — Portekiz kuzey kıyısını daraltıyor","gun":"1549","yer":"Arzila (Asîlâ) — Fas kuzey kıyısı","kisiler":"III. João (Portekiz kralı), Muhammed eş-Şeyh","d":"Malî bunalım ve Sa'dî baskısının birleşmesiyle III. João, 1471'den beri elde tutulan Arzila'yı boşalttı. Portekiz'in Fas'taki varlığı böylece Sebte, Tanca ve Mazagan'a indi. Arzila 1577'de kısa süre yeniden işgal edilecek, 1589'da kesin olarak bırakılacaktı.","kaynak":"fas","duygu":["😔"],"yer_id":"Arzila (Asilah)"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1769-03-11","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"kapsam":"dis","b":"Mazagan'ın boşaltılması — Portekiz'in Fas'taki son mevzii düştü","gun":"11 Mart 1769 (tahliye filosu Lizbon'dan 1 Şubat'ta hareket etti)","yer":"Mazagan (el-Cedîde) — Fas Atlas kıyısı","kisiler":"Sultan III. Muhammed b. Abdullah, Dinis Gregório (vali), Bernardo Ramires Esquível","d":"Alevî sultanı III. Muhammed b. Abdullah'ın 1769 başında başlattığı kuşatma karşısında 592 kişilik garnizon tutunamadı; Lizbon'dan 1 Şubat'ta yola çıkan tahliye filosu 11 Mart 1769'da son askerleri gemiye aldı ve şehri en son vali Dinis Gregório terk etti. Böylece 1415'te Sebte'nin alınmasıyla başlayan Portekiz'in Fas'taki varlığı üç buçuk asır sonra sona erdi. Mazagan, 1541'deki genel çöküşten sonra elde tutulan tek Atlas kıyısı mevziiydi ve iki yüz elli beş yılla Portekiz'in Fas'ta en uzun tuttuğu yer oldu.","duygu":["😔"],"yer_id":"Mazagan (El Jadida)","kaynak":"TDV İslâm Ansiklopedisi, MEVLÂY MUHAMMED III (islamansiklopedisi.org.tr/mevlay-muhammed-iii); A. O. Vieira Júnior, 'Do rei, do juiz e da escravizada...', Outros Tempos 23/42 (2026) — «TDV: «Mevlây Muhammed 1182’de (1768-69) 70.000 kişilik bir orduyla Portekizliler’den Mâzâgân’ı geri aldı.» / Outros Tempos özeti: fortaleza «evacuada em 1769 sob as ordens do monarca português D. José»"},{"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1417-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi"],"kapsam":"dis","onem":2,"b":"Bahreyn adalarının Cebrîler'in eline geçmesi","gun":"1417 dolayı (Cebrî hânedanının kuruluşu XV. yüzyıl başına tarihlenir)","yer":"Bahreyn (Evâl adaları), Katîf, Lahsa","d":"TDV Bahreyn maddesi adanın \"sırasıyla Uyûnîler, Salgurlular, Tabîler, Cebrîler idaresinde kaldığı ve Cebrîler devrinde çoğunluğun Şiîler'den Sünnîler'e geçtiği\" kaydını düşer; hiçbirine tarih vermez. Genel literatürde Cebrî hanedanı XV. yüzyılın başında, Katîf'teki son Cervânî hükümdarını devirerek kuruldu ve en parlak devrinde (Acvâd b. Zâmil, ö. 1496) Basra körfezinin bütün Arap kıyısını, Lahsa'yı, Katîf'i ve Bahreyn adalarını denetledi. Acvâd'ın ardından Evâl adaları Mukrin b. Zâmil'e geçti — 1521'de Portekizliler'e yenilecek olan hükümdar odur.","kaynak":"bahreyn","duygu":["🏛"],"yer_id":"Manama (Bahreyn)"},{"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":2,"t":"1521-01-01","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"kapsam":"dis","onem":4,"b":"Portekiz'in Bahreyn'i alışı — Cebrî hâkimiyetinin sonu","gun":"1521","yer":"Bahreyn (Evâl adaları)","kisiler":"António Correia, Mukrin b. Zâmil (Cebrî hükümdarı)","d":"Cebrî hükümdarı Mukrin b. Zâmil'in Hürmüz'e vergi ödemeyi reddetmesi üzerine Portekiz donanması ile Portekiz'e tâbi Hürmüz Krallığı'nın kuvvetleri adaya çıktı; Mukrin savaşta yenildi ve Bahreyn 1521'de Portekiz idaresine girdi. Ada bundan sonra seksen yıl boyunca Hürmüz üzerinden, çoğunlukla Sünnî İranlı valiler eliyle yönetildi. Bahreyn'in incisi ve stratejik konumu, adayı körfezdeki Osmanlı-Portekiz çekişmesinin doğrudan hedefi hâline getirecekti.","kaynak":"bahreyn","duygu":["😔"],"yer_id":"Manama (Bahreyn)"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1559-01-01","k":"sefer","etiket":["savas","konu-askeri"],"b":"Osmanlı'nın Bahreyn seferi — körfezde Portekiz'e karşı son büyük hamle","gun":"1559 (gün ve ay hiçbir kaynakta yok)","yer":"Bahreyn (Evâl adaları)","kisiler":"Mustafa Paşa (Lahsa beylerbeyi)","d":"Basra'nın 1546'da ilhakı ve Lahsa eyaletinin kurulmasıyla körfezin Arap kıyısına yerleşen Osmanlı Devleti, adanın inci ticaretini ve Portekiz'in Hürmüz hattını hedef alarak Lahsa beylerbeyi Mustafa Paşa kumandasında Bahreyn üzerine yürüdü. Seferin sonucu kaynaklarda ayrışır: TDV İslâm Ansiklopedisi Osmanlılar'ın \"1559 yılında Bahreyn'i ele geçirip orada bir üs\" kurduğunu, adaların \"daha sonra tekrar Portekizliler'in idaresine\" geçtiğini yazar; batı literatürü ise kuşatmanın başarısız olduğunu, Hürmüz'den denizden gelen Portekiz takviyesinin Osmanlı kuvvetlerini püskürttüğünü ve her iki tarafı da kıran bir veba salgınının ardından Osmanlılar'ın teslim şartları istediğini kaydeder. İki anlatı sonucun kendisinde ayrılır; ortak olan, Bahreyn'in Osmanlı elinde kalıcı olmadığıdır.","kaynak":"bahreyn","duygu":["🐎","😔"],"yer_id":"Manama (Bahreyn)"},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":2,"t":"1602-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi"],"kapsam":"dis","b":"Safevîler'in Bahreyn'i Portekiz'den alması","gun":"1602","yer":"Bahreyn (Evâl adaları)","kisiler":"Şah I. Abbas, Allahverdi Han","d":"Şah I. Abbas'ın gönderdiği kuvvetler adadaki isyancılarla birleşerek Portekiz garnizonunu kaleden çıkardı; TDV'nin ifadesiyle adalar \"1602'de İran'a bağlı kuvvetler tarafından\" Portekizliler'in elinden alındı. Bahreyn böylece seksen bir yıllık Portekiz idaresinden çıkıp Safevî hâkimiyetine girdi ve yüz on beş yıl İran'a bağlı kaldı. Bu, Portekiz'in körfezdeki çözülmesinin ilk halkasıdır; yirmi yıl sonra Hürmüz'ün kendisi de İngiliz-İran ortak harekâtıyla düşecekti.","kaynak":"bahreyn","duygu":["🏛"],"yer_id":"Manama (Bahreyn)"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1717-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi"],"kapsam":"dis","b":"Ummanlılar'ın Bahreyn'i istilâsı — Safevî hâkimiyetinin sonu","gun":"1717 (gün ve ay kaynakta yok)","yer":"Bahreyn (Evâl adaları)","d":"Safevî Devleti'nin son yıllarındaki çözülme sırasında Ya'rubî hanedanı idaresindeki Umman donanması adayı istilâ etti ve Safevî hâkimiyeti sona erdi. Bunu izleyen otuz beş yıl körfezin en karışık dönemidir: ada Umman, İran ve yerel Arap güçleri arasında birkaç kez el değiştirdi.","kaynak":"bahreyn","duygu":["🏛"],"yer_id":"Manama (Bahreyn)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","bolge":1,"t":"1753-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi"],"kapsam":"dis","b":"Bahreyn'in Bûşehr'deki Âl-i Mezkûr idaresine geçmesi","gun":"1753 (gün ve ay kaynakta yok)","yer":"Bahreyn (Evâl adaları), Bûşehr","kisiler":"Âl-i Mezkûr ailesi","d":"Aslen Umman'dan gelip Bûşehr'e yerleşen ve Huvele sayılan Âl-i Mezkûr ailesi, 1753'te Bûşehr'deki üslerinden hareketle Bahreyn'i idareleri altına aldı. Aile İran'ın körfez kıyısındaki Arap topluluklarına önderlik ediyor ve adayı İran adına yönetiyordu; son temsilcisi Nasr Âl-i Mezkûr, Bahreyn valiliğine Zend idaresince atanmıştı. Bu, adanın Âl-i Halîfe'den önceki son yönetimidir.","kaynak":"bahreyn","duygu":["🏛"],"yer_id":"Manama (Bahreyn)"},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","bolge":1,"t":"1783-01-01","k":"siyaset","etiket":["siyaset","konu-siyasi","konu-hanedan"],"kapsam":"dis","b":"Âl-i Halîfe'nin Bahreyn'i fethi — bugüne kadar süren hanedanın kuruluşu","gun":"1783","yer":"Bahreyn (Evâl adaları), Zübâre — Katar yarımadası","kisiler":"Ahmed b. Muhammed b. Halîfe, Nasr Âl-i Mezkûr","d":"Zend idaresinin Bahreyn valisi Nasr Âl-i Mezkûr, Katar yarımadasındaki Zübâre'yi kuşattı; Ahmed b. Muhammed b. Halîfe kumandasındaki Utûb kuvvetleri kuşatmayı kırdı ve karşı taarruza geçerek aynı yıl Bahreyn'i aldı. TDV'nin kaydı kısadır: \"Bahreyn 1783 yılında Utûb kabilesinden Âl-i Halîfe'nin hâkimiyetine girdi.\" Ahmed b. Muhammed bu zaferden sonra \"el-Fâtih\" lakabıyla anıldı ve kurduğu hanedan adada bugüne kadar hüküm sürdü.","kaynak":"bahreyn","duygu":["🏛"],"yer_id":"Manama (Bahreyn)"},{"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","bolge":2,"t":"1861-05-21","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"kapsam":"dis","onem":3,"b":"Bahreyn'in İngiltere ile antlaşması — körfezde himaye düzenine giriş","gun":"21 Mayıs 1861","yer":"Bahreyn (Evâl adaları)","kisiler":"Şeyh Muhammed b. Halîfe, kardeşi Ali","d":"TDV'nin kaydına göre \\\"21 Mayıs 1861'de İngiltere ile Bahreyn'i temsilen Şeyh Muhammed'in kardeşi Ali, bölgede köle ticaretini ve korsanlığı meneden bir anlaşma imzaladılar\\\"; İngiliz belgelerinde aynı antlaşma (Perpetual Truce of Friendship and Peace) 31 Mayıs 1861 tarihini taşır. Antlaşma Bahreyn'in dış ilişkilerini İngiltere'ye bağlayan himaye düzeninin ilk halkasıdır ve ada, Osmanlı'nın 1871'de Lahsa ile Katîf'e yeniden yerleşmesinden sonra da bu düzenin dışında kaldı.","kaynak":"bahreyn","duygu":["🤝"],"yer_id":"Manama (Bahreyn)"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","odak_yer":["Mardin","Diyarbakır"],"t":"1517-05-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri"],"b":"Mardin kalesinin teslimi — Diyarbekir'in güneyinde Safevî direncinin sonu","gun":"Mayıs 1517","yer":"Mardin, Diyarbekir","yer_id":"Mardin","kisiler":"Bıyıklı Mehmed Paşa, Kara Han (Safevî valisi)","d":"Çaldıran'dan sonra Diyarbekir bölgesine yürüyen Bıyıklı Mehmed Paşa Mardin'i kuşattığında Safevî kuvvetleri Ekim 1515'te kaleye çekildi; şehir Osmanlı eline geçtiği hâlde kale direndi. Safevî valisi Kara Han'ın takviyeyle karşı taarruza geçmesi Mayıs 1516'daki Koçhisar (Kızıltepe) Savaşı'yla sonuçlandı — Dede Garkın sahrasında bütün gün süren muharebede Kara Han'ın başı kesildi ve ordusu dağıldı. Kale ise TDV'nin ifadesiyle \"ancak dokuz ay sonra\" teslim oldu.","kaynak":"mardin · [TDV: biyikli-mehmed-pasa]","duygu":["🎉"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"taht","kapsam":"ic","t":"1362-03-01","k":"taht","etiket":["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"],"b":"Orhan Gazi'nin vefatı — beylikten devlete geçen kırk yılın sonu","gun":"Mart 1362","yer":"Bursa","yer_id":"Bursa","kisiler":"Orhan Gazi, I. Murad, Süleyman Paşa","d":"Osman Gazi'nin 1324'te ölümüyle beyliğin başına geçen Orhan Gazi, otuz sekiz yıllık idaresinde Osmanlı'yı bir uç beyliğinden Marmara'nın iki yakasına oturmuş bir devlete dönüştürdü: Bursa (1326), İznik (1331) ve İzmit (1337) alındı, Karesi Beyliği ilhak edildi, ilk akçe basıldı (1327), ilk medrese İznik'te kuruldu (1331) ve Rumeli'ye geçiş Çimpe (1352) ile Gelibolu (1354) üzerinden kalıcı hâle geldi. Rumeli fütuhatını yürüten büyük oğlu Süleyman Paşa'yı 1357'de bir av kazasında kaybetti; kendisi Mart 1362'de Bursa'da vefat etti ve yerine oğlu I. Murad geçti.","vefat_id":"orhan","duygu":["👑"],"kaynak":"TDV İslâm Ansiklopedisi, «Murad I» md., https://islamansiklopedisi.org.tr/murad-i (okundu) — «Sultan Orhan'ın ölümü haberi geldi (Cemâziyelevvel 763 / Mart 1362).»"}];

;
